  questions: [
  {"id":"C4-001","ch":4,"no":1,"q":"데이터 모델링 단계에 대한 설명으로 가장 적절하지 않은 것은?","c":["물리 데이터 모델링은 논리 데이터 모델의 산출물을 특정 DBMS에서 이해하고 처리할 수 있도록 하는 과정이다","오늘날 개념 데이터 모델링과 논리 데이터 모델링은 반드시 엄격히 구분하여 별도의 산출물로 관리해야 한다","개념 데이터 모델링은 추상화를 통하여 개념 세계에서 정보의 구조와 업무 규칙을 ERD로 표현해 가는 과정이다","논리 데이터 모델링은 개념 데이터 모델을 특정 DB(계층형·망형·관계형)로 구현할 것을 결정하고 그 구조로 표현하는 것이다"],"a":1,"e":"오늘날에는 개념 데이터 모델링과 논리 데이터 모델링을 명확히 구분하지 않고 합쳐서 논리 데이터 모델링(또는 데이터 모델링)이라 부른다.","s":"1장 1절 데이터 모델링 정의"},
  {"id":"C4-002","ch":4,"no":2,"q":"정보시스템 개발 방법론과 주요 기법의 연결이 옳지 않은 것은?","c":["객체지향 방법론 - 객체 모형, Use Case Diagram, 분석·설계 패턴, 반복·점진 개발","컴포넌트 기반 방법론 - 자료흐름도(DFD), 구조적 프로그램, 3세대 언어","구조적 방법론 - 기능 모형, 자료흐름도(DFD), 구조적 프로그램","정보공학 방법론 - 데이터 모형, 엔터티관계도(ERD), 프로세스 계층도, 폭포수 개발"],"a":1,"e":"컴포넌트 기반 방법론의 주요 기법은 컴포넌트 모형, Class Diagram, 컴포넌트 명세·추출·연동, 아키텍처 설계이다.","s":"1장 1절 정보 시스템 개발 방법론"},
  {"id":"C4-003","ch":4,"no":3,"q":"정보공학 방법론(IEM)에 대한 설명으로 가장 적절하지 않은 것은?","c":["정보 아키텍처는 데이터 아키텍처와 프로세스 아키텍처로 구성되며 업무 영역 분석 단계의 입력이 된다","조직 아키텍처는 시스템 아키텍처의 기반 기술 구조를 형성한다","James Martin이 제시하였으며 데이터와 프로세스를 병행 분석하면서도 데이터에 좀 더 초점을 맞춘다","정보 전략 계획(ISP) 단계에서 아키텍처 모델링을 수행한다"],"a":1,"e":"시스템 아키텍처의 기반 기술 구조를 형성하는 것은 기술 아키텍처이며, 조직 아키텍처는 정보·시스템·기술 아키텍처의 구현을 담당한다.","s":"1장 1절 정보공학 방법론"},
  {"id":"C4-004","ch":4,"no":4,"q":"'정보의 고립화' 현상의 원인으로 제시된 것으로만 묶인 것은?","c":["데이터 일관성 유지 불가능 / 시스템 통합의 한계","의사소통 문제 / 업무 요구에 비탄력적","전사 데이터 모델 기반 없이 시스템 개발 / 복잡한 업무 흐름에 의한 중복된 데이터","불필요한 개발과 과다한 유지보수 비용 / 낮은 생산성"],"a":2,"e":"정보 고립화의 '원인'은 전사 데이터 모델 기반 부재와 중복된 데이터이며, 나머지는 '현상'에 해당한다.","s":"1장 1절 정보의 고립화"},
  {"id":"C4-005","ch":4,"no":5,"q":"데이터 모델링에서 다루는 대상에 대한 설명으로 가장 적절한 것은?","c":["데이터 모델링은 화면 설계와 동일한 활동이다","데이터 모델링은 물리적 저장 구조를 우선 결정하는 활동이다","논리 데이터 모델링에서 다루는 대상은 '맞다/틀리다'로 답할 수 있는 '업무에서 발생하는 사실'이다","데이터 모델링은 프로그램의 처리 알고리즘을 정의하는 것이다"],"a":2,"e":"논리 데이터 모델링은 업무에서 발생하는 사실(참/거짓 판별 가능한 사실명제)을 다룬다.","s":"1장 1절 데이터 모델링의 중요성"},
  {"id":"C4-006","ch":4,"no":6,"q":"데이터 무결성(Data Integrity)의 정의로 가장 적절한 것은?","c":["관계형 테이블에 관계형 연산을 수행할 때 테이블 내 데이터 값의 정확성과 일관성을 보장하는 일련의 업무 규칙","데이터베이스의 물리적 저장 구조를 최적화하는 기법","데이터를 백업하고 복구하는 절차","데이터의 암호화 및 접근 통제 정책"],"a":0,"e":"데이터 무결성은 입력·수정·삭제·조회 시 데이터 값의 정확성과 일관성을 보장하는 일련의 업무 규칙이다.","s":"1장 1절 데이터 모델링의 중요성"},
  {"id":"C4-007","ch":4,"no":7,"q":"모델링 기본 원칙 중 '모델링 상세화 원칙(Granularity Principle)'에 대한 설명으로 가장 적절한 것은?","c":["요구 사항은 모든 사람들이 이해할 수 있도록 명확하게 공표되어야 한다","데이터는 데이터의 본질과 잠재적 사용을 이해할 수 있을 만큼 상세화되어야 한다","모델은 물리적 제약 조건 없이 비즈니스를 그대로 반영해야 한다","논리 데이터 모델은 특정 아키텍처·기술·제품과 독립적이다"],"a":1,"e":"1번은 커뮤니케이션 원칙, 3·4번은 논리적 표현 원칙에 대한 설명이다.","s":"1장 1절 (2013 Edition) 모델링 기본 원칙"},
  {"id":"C4-008","ch":4,"no":8,"q":"논리 데이터 모델에서 물리 데이터 모델로의 이동에 대한 설명으로 옳은 것은?","c":["보통 수준의 상세화에서 발생하는 변환(Transformation) 과정이다","추상화(Abstraction) 과정이다","정규화(Normalization) 과정이다","분해(Decomposition) 과정이다"],"a":0,"e":"많은 모델러가 논리→물리 이동을 분해로 오해하지만, 이는 분해가 아니라 변환(Transformation)이다.","s":"1장 1절 모델링 상세화 원칙"},
  {"id":"C4-009","ch":4,"no":9,"q":"좋은 데이터 모델의 요소에 해당하지 않는 것은?","c":["간결성(Elegance)","고성능(High Performance)","완전성(Completeness)","중복 배제(Non-Redundancy)"],"a":1,"e":"좋은 데이터 모델의 요소는 완전성, 중복 배제, 비즈니스 룰, 데이터 재사용, 안정성 및 확장성, 간결성, 의사소통, 통합성이다.","s":"1장 1절 좋은 데이터 모델의 요소"},
  {"id":"C4-010","ch":4,"no":10,"q":"좋은 데이터 모델의 요소 중 '간결성(Elegance)'의 기본적인 전제로 제시된 것은?","c":["분리","중복","정규화","통합"],"a":3,"e":"간결한 모델의 기본적인 전제는 통합이다. 합리적으로 정돈된 방법으로 데이터를 통합하여 집합을 정의해야 한다.","s":"1장 1절 좋은 데이터 모델의 요소"},
  {"id":"C4-011","ch":4,"no":11,"q":"좋은 데이터 모델의 요소 중 '데이터 재사용(Data Reusability)'을 향상시키기 위해 충분히 고려해야 할 두 가지는?","c":["데이터의 정확성과 완전성","데이터의 성능과 가용성","데이터의 보안성과 무결성","데이터의 통합성과 독립성"],"a":3,"e":"데이터 재사용성을 향상시키려면 데이터의 통합성과 독립성을 충분히 고려해야 한다.","s":"1장 1절 좋은 데이터 모델의 요소"},
  {"id":"C4-012","ch":4,"no":12,"q":"데이터 모델링 시 주의점 중 '비일관성(Inconsistency)'에 대한 설명으로 가장 적절한 것은?","c":["모델이 지나치게 추상화되어 이해하기 어려운 것","데이터베이스의 여러 장소에 같은 정보를 저장하는 잘못","사소한 업무 변화에도 데이터 모델이 수시로 변경되는 것","데이터의 중복이 없더라도 신용 상태 갱신 없이 납부 이력만 갱신하는 것처럼 다른 데이터와 모순되게 수정하는 것"],"a":3,"e":"비일관성은 데이터 중복이 없더라도 다른 데이터와 모순됨을 고려하지 않고 데이터를 수정할 때 발생한다.","s":"1장 1절 데이터 모델링 시 주의점"},
  {"id":"C4-013","ch":4,"no":13,"q":"데이터 설계가 중요한 이유 중 '파급 효과(Leverage)'에 대한 설명으로 가장 적절한 것은?","c":["시스템 구축 완성 시점에 데이터 모델을 변경하면 표준·응용 영향 분석과 변경 작업이 대규모로 발생하여 큰 위험 요소가 된다","데이터 모델은 정보 요구 사항과 한계를 명확하고 간결하게 표현할 수 있는 도구이다","데이터 구조의 문제로 인한 데이터 품질 문제는 치유하기 불가능한 경우가 대부분이다","데이터 모델은 의사소통의 도구로서 역할을 한다"],"a":0,"e":"2번은 간결한 표현(Conciseness), 3번은 데이터 품질(Data Quality)에 대한 설명이다.","s":"1장 1절 데이터 모델링 필요성"},
  {"id":"C4-014","ch":4,"no":14,"q":"추상화 기법 중 '유형화(Classification)'에 대한 설명으로 옳은 것은?","c":["둘 또는 그 이상의 엔터티 타입 요소 간에 서브세트를 정의하며 IS-A 관계를 갖는다","엔터티를 물리적 테이블로 변환하는 개념이다","같은 성질을 갖는 멤버들을 타입 또는 유형이라는 하나의 개념으로 정의하며 IS-MEMBER-OF 관계를 갖는다","속성 타입들의 세트로 구성되는 새로운 타입을 정의하며 IS-PART-OF 관계를 갖는다"],"a":2,"e":"유형화는 IS-MEMBER-OF, 집단화는 IS-PART-OF, 일반화는 IS-A 관계를 갖는다.","s":"1장 2절 추상화"},
  {"id":"C4-015","ch":4,"no":15,"q":"추상화 기법 중 '집단화(Aggregation)'의 예시로 가장 적절한 것은?","c":["'자동차'의 부분집합으로 '승용차', '버스', '트럭'을 정의하는 것","'사원'과 '고객'을 통합하여 'Party'로 정의하는 것","'소나타'를 어떤 회사에서는 '상품', 다른 회사에서는 '고정자산' 엔터티 타입으로 정의하는 것","'핸들', '바퀴', '페달'이라는 속성 타입들을 모아 '자전거' 엔터티 타입을 정의하는 것"],"a":3,"e":"집단화는 값을 유형화한 속성 타입들의 세트로 새로운 엔터티 타입을 정의하는 개념이다.","s":"1장 2절 추상화"},
  {"id":"C4-016","ch":4,"no":16,"q":"일반화(Generalization)에 대한 설명으로 가장 적절하지 않은 것은?","c":["둘 또는 그 이상의 엔터티 타입 요소 간에 서브세트를 정의하는 개념이다","슈퍼타입에 정의된 모든 특성은 서브타입으로 상속된다","서브타입에 정의된 개별 속성은 슈퍼타입으로 상속된다","여러 엔터티 타입 간의 공통적인 특성을 파악하는 과정이다"],"a":2,"e":"상속은 슈퍼타입(전체집합)에서 서브타입(부분집합) 방향으로 이루어지며, 서브타입의 개별 속성이 슈퍼타입으로 상속되지는 않는다.","s":"1장 2절 추상화"},
  {"id":"C4-017","ch":4,"no":17,"q":"타입과 인스턴스의 대응 관계로 옳지 않은 것은?","c":["엔터티 타입(type)은 엔터티(instance)의 집합이다","관계(type)는 페어링(instance)의 집합이다","속성(type)은 값(instance)의 집합이다","클래스(type)는 엔터티(instance)의 집합이다"],"a":3,"e":"오브젝트·컴포넌트 모델에서 클래스(Class)에 대응하는 인스턴스는 객체(Object)이다.","s":"1장 2절 타입과 인스턴스"},
  {"id":"C4-018","ch":4,"no":18,"q":"엔터티에 대한 설명으로 가장 적절하지 않은 것은?","c":["엔터티의 정의가 달라져도 인스턴스들의 구성은 변하지 않는다","조직의 업무를 수행하는 데 필요로 하는 사물, 사건 또는 개념을 나타내는 어떤 것이다","동일한 업무 행위를 하는 단일 개념으로 정의한 인스턴스들의 집합체이다","유사한 속성을 갖는 단일 개념으로 정의한 멤버들의 집합체이다"],"a":0,"e":"엔터티를 어떻게 정의하느냐(동일한 성질을 어디까지로 한정할 것인가)에 따라 인스턴스들의 구성이 달라질 수 있다.","s":"1장 2절 엔터티"},
  {"id":"C4-019","ch":4,"no":19,"q":"관계(Relationship)의 역할 및 중요성에 대한 설명으로 옳은 것으로만 묶인 것은?\nㄱ. 여러 개의 엔터티를 조인하여 정보를 조회할 수 있다\nㄴ. 중복 데이터를 배제하는 데 도움이 되므로 데이터 정확성 향상에 기여한다\nㄷ. 관계는 반드시 서로 다른 두 엔터티 사이에만 존재한다\nㄹ. 관계는 페어링의 집합이다","c":["ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ","ㄱ, ㄷ, ㄹ","ㄱ, ㄴ, ㄹ"],"a":3,"e":"관계는 하나 또는 두 개의 엔터티에서 인스턴스를 연관시키므로 자기참조 관계와 같이 하나의 엔터티 내에서도 존재할 수 있다. 따라서 ㄷ은 틀리다.","s":"1장 2절 관계"},
  {"id":"C4-020","ch":4,"no":20,"q":"엔터티 무결성(Entity Integrity) 규칙에 해당하지 않는 것은?","c":["일련의 식별자 속성은 반드시 값을 갖는다","일련의 식별자 속성의 값은 유일하다","식별자를 구성하는 일련의 속성은 최소한의 개수로 해야 한다","식별자 속성은 반드시 하나의 속성으로만 구성되어야 한다"],"a":3,"e":"식별자는 하나 또는 하나 이상의 속성으로 구성될 수 있으며, 최소한의 개수라는 것이 단일 속성만을 의미하지는 않는다.","s":"1장 2절 식별자"},
  {"id":"C4-021","ch":4,"no":21,"q":"정보공학(IE) 엔터티 표기법에서 '특성(Characteristic) 엔터티'에 대한 설명으로 옳은 것은?","c":["하나의 인스턴스에 여러 번 발생하는 속성의 그룹으로 한 개의 식별 부모만을 갖는다","두 개 이상의 연관된 다른 엔터티로부터 식별자를 상속받는다","다른 부분집합과 구별되는 공통 속성이나 관계를 공유하는 엔터티 부분집합이다","하나의 인스턴스를 식별하는 데 다른 인스턴스에 의존하지 않는다"],"a":0,"e":"2번은 연관(Associative) 엔터티, 3번은 서브타입 엔터티, 4번은 독립 엔터티이다.","s":"1장 3절 엔터티 표기법"},
  {"id":"C4-022","ch":4,"no":22,"q":"CASE*Method(바커) 표기법의 'UID Bar'에 대한 설명으로 옳은 것은?","c":["관계가 선택적임을 나타낸다","관계의 기수성이 다대다임을 나타낸다","서브타입의 배타성을 나타낸다","부모의 유일식별자 속성이 자식의 유일 식별자 속성의 일부 또는 전체가 될 때 표시한다"],"a":3,"e":"UID Bar는 부모의 유일식별자 속성이 자식의 유일 식별자 속성의 일부 또는 전체가 될 때 관계선에 표시한다.","s":"1장 3절 엔터티 표기법"},
  {"id":"C4-023","ch":4,"no":23,"q":"속성 표기법에 대한 설명으로 옳지 않은 것은?","c":["필수(Mandatory) 속성은 CASE*Method 표기법에서 '*'로 표시하며 물리 설계 시 NOT NULL로 표기한다","선택(Optional) 속성은 CASE*Method 표기법에서 'o'로 표시하며 물리 설계 시 NULL로 표기한다","유일 식별자는 '#'로 표시한다","외래 식별자는 다른 엔터티로부터 상속받은 속성으로 반드시 필수 속성이어야 한다"],"a":3,"e":"부모·자식 양쪽 모두 선택 관계이면 외래 키 속성 값을 Null 처리할 수 있으므로 외래 식별자가 반드시 필수 속성인 것은 아니다.","s":"1장 3절 속성 표기법"},
  {"id":"C4-024","ch":4,"no":24,"q":"관계 선택성의 '현재' 결정 방법에 대한 설명으로 옳은 것은?","c":["다른 엔터티에 어떤 행을 입력하기 전에 상대 엔터티에 적어도 한 건의 행이 반드시 있어야만 하는 경우 필수 관계이다","관계 읽기를 통하여 '일 수도(May)'이면 필수 관계이다","기수성이 1:M이면 항상 필수 관계이다","관계 읽기를 통하여 '반드시(Must)'이면 필수 관계이다"],"a":0,"e":"과거에는 관계 읽기(Must/May)로 판단했으나, 현재는 행 입력 시점에 상대 엔터티에 행이 반드시 있어야 하는지를 기준으로 판단한다.","s":"1장 3절 관계 선택성 표기법"},
  {"id":"C4-025","ch":4,"no":25,"q":"식별 관계(Identifying Relationship)에 대한 설명으로 가장 적절하지 않은 것은?","c":["자식 엔터티의 인스턴스를 식별할 때 반드시 부모 엔터티의 인스턴스를 먼저 식별해야 한다","IE 표기법에서는 점선으로 표현한다","부모 엔터티의 식별자가 자식 엔터티의 식별자의 일부분이 되는 관계이다","자식 엔터티는 부모 엔터티에 대하여 존재 종속적이고 식별 종속적이다"],"a":1,"e":"식별 관계는 IE 표기법에서 실선, 비식별 관계는 점선으로 표현한다.","s":"1장 3절 관계 식별성 표기법"},
  {"id":"C4-026","ch":4,"no":26,"q":"비식별 관계(Non-Identifying Relationship)에 대한 설명으로 옳은 것은?","c":["CASE*Method 표기법에서 UID Bar로 표시한다","부모 엔터티의 식별자가 자식 엔터티의 일반 속성으로 표현되며, 자식은 존재 종속적이지만 식별 종속적이지는 않다","부모 엔터티의 식별자가 자식 엔터티의 식별자 일부가 된다","자식 엔터티는 부모 엔터티에 대하여 존재 종속적이지 않다"],"a":1,"e":"비식별 관계는 부모 식별자가 자식의 일반 속성이 되며 존재 종속적이지만 식별 종속적이지는 않다.","s":"1장 3절 관계 식별성 표기법"},
  {"id":"C4-027","ch":4,"no":27,"q":"바커 표기법(Barker Notation)에 대한 설명으로 옳지 않은 것은?","c":["오라클에서 Case Method로 채택하였다","배타적(Arc) 관계를 표현할 수 있다","까마귀 발 모델(Crow's Foot Model)이라고도 불린다","Richard Barker, Ian Palmer, Harry Ellis 등에 의해 1986년 개발되었다"],"a":2,"e":"까마귀 발 모델로 불리는 것은 I/E 표기법이다.","s":"1장 3절 데이터 모델링 표기법 이해"},
  {"id":"C4-028","ch":4,"no":28,"q":"I/E 표기법(Information Engineering Notation)에 대한 설명으로 옳은 것은?","c":["Peter Chen이 1976년에 제안하였다","Richard Barker가 1986년에 개발하였다","E.F. Codd가 1970년에 발표하였다","Clive Finkelstein과 James Martin이 공동 저술·발표하였고 1980년대 중반 James Martin에 의해 체계가 정리되었다"],"a":3,"e":"I/E 표기법은 Clive Finkelstein과 James Martin이 공동 저술·발표하였고 1980년대 중반 James Martin에 의해 체계화되었다.","s":"1장 3절 데이터 모델링 표기법 이해"},
  {"id":"C4-029","ch":4,"no":29,"q":"서브타입의 배타성·포괄성에 대한 교재 기술로 옳지 않은 것은?","c":["바커 표기법 절에서는 서브타입이 서브타입의 중복을 허락하지 않는 상호 배타적이라고 기술한다","I/E 표기법 절에서는 서브타입이 배타적 또는 포괄적일 수 있다고 기술한다","바커 표기법에서는 포괄적(Inclusive) 서브타입을 직접 표현할 수 있다","제2절 데이터 모델링 기법 이해에서는 서브타입이 배타적(Exclusive) 또는 포괄적(Inclusive)일 수 있다고 기술한다"],"a":2,"e":"CASE*Method(바커) 표기법에서는 포괄적 일반화 표현이 불가능하며, 서브타입은 상호 배타적이다.","s":"1장 3절 표기법 비교"},
  {"id":"C4-030","ch":4,"no":30,"q":"확장된 개체-관계 모델(Extended ERD)에 대한 설명으로 옳은 것은?","c":["개체-관계 모델에 물리 저장 구조가 추가된 것이다","개체-관계 모델에 객체지향 상속 개념이 추가된 것이다","개체-관계 모델에 서브타입이 추가되면서 만들어졌으며 오늘날 ERD라 하면 이를 의미한다","개체-관계 모델에 정규화 개념이 추가된 것이다"],"a":2,"e":"E-ERD는 개체-관계 모델에 서브타입이 추가되면서 만들어졌으며 오늘날 ERD는 이를 의미한다.","s":"1장 2절 개체-관계 모델 기법"},
  {"id":"C4-031","ch":4,"no":31,"q":"개체-관계 모델(ERD)을 사용하는 목적으로 제시된 것으로만 묶인 것은?","c":["보안 정책 수립 / 접근 통제","백업 전략 수립 / 복구 시간 단축","관리자·사용자·개발자들이 서로 다르게 인식하는 뷰를 하나로 통합한 단일화된 설계안 작성 / 서로 다른 뷰를 충족시킬 수 있는 데이터 처리와 제약 조건 등 요구 사항 정의","데이터베이스 성능 최적화 / 저장 공간 절감"],"a":2,"e":"ERD의 목적은 서로 다른 뷰의 통합된 단일 설계안 작성과 요구 사항(데이터 처리·제약 조건) 정의이다.","s":"1장 2절 개체-관계 모델 기법"},
  {"id":"C4-032","ch":4,"no":32,"q":"객체지향 모델링과 논리 데이터 모델링의 대응 관계로 옳지 않은 것은?","c":["객체 ↔ 엔터티 (객체는 프로세스를 포함한다는 차이가 있다)","연결(Link) ↔ 관계(Relationship)","캡슐화 ↔ 정규화","객체 클래스 ↔ 엔터티 유형"],"a":2,"e":"캡슐화에 대응하는 논리 데이터 모델링의 개념은 없다.","s":"1장 2절 객체지향 모델링"},
  {"id":"C4-033","ch":4,"no":33,"q":"객체지향 모델링의 장점으로 제시되지 않은 것은?","c":["데이터의 물리적 저장 효율을 극대화한다","재사용 코드와 같은 개념이 실제로 가능한 환경을 제공한다","모든 비즈니스 규칙이 표현될 수 있는 유일한 환경을 제공한다","프로세스와 데이터 모델링을 함께 운영한다"],"a":0,"e":"물리적 저장 효율 극대화는 객체지향 모델링의 장점으로 제시되지 않았다.","s":"1장 2절 객체지향 모델링"},
  {"id":"C4-034","ch":4,"no":34,"q":"개괄 데이터 모델에 대한 (2013 Edition) 설명으로 가장 적절하지 않은 것은?","c":["상위 주제 영역 수준의 데이터 구성도가 이에 해당한다","데이터 영역과 데이터 집합을 업무 영역에 국한하여 정의한다","각 데이터 영역은 다른 데이터 영역과 관계를 가질 수 있다","전사 데이터 영역 모델로 계획자 관점에 해당한다"],"a":1,"e":"개괄 데이터 모델은 데이터 영역과 데이터 집합을 업무 영역에 국한하지 않고 전사적 관점에서 정의한다.","s":"1장 2절 (2013 Edition) 개괄 데이터 모델"},
  {"id":"C4-035","ch":4,"no":35,"q":"개념 데이터 모델에 대한 (2013 Edition) 설명으로 옳지 않은 것은?","c":["주제 영역을 정의하고 주제 영역 내의 핵심 엔터티를 도출하여 그들 간의 관계를 정의하는 것이다","전사 수준에서 사용하는 데이터를 전체적으로 표현할 수 있는 기본 틀이다","핵심 엔터티는 일반적으로 단위 주제 영역별로 한두 개 정도가 도출된다","개념 데이터 모델은 주제 영역 상위 계층에 위치한다"],"a":3,"e":"개괄 데이터 모델이 주제 영역 상위, 개념 데이터 모델이 주제 영역 하위에 위치한다.","s":"1장 2절 (2013 Edition) 개념 데이터 모델"},
  {"id":"C4-036","ch":4,"no":36,"q":"개념 데이터 모델의 의의에 대한 설명으로 가장 적절하지 않은 것은?","c":["주요 엔터티로 한정을 지을 뿐 논리 모델링 기법과 동일하다","개념 데이터 모델도 상세화가 진행될 수 있다","상세화되더라도 전체적인 골격의 개념적 모델을 벗어나서는 안 된다","개념 데이터 모델은 논리 데이터 모델과 완전히 다른 기법을 사용한다"],"a":3,"e":"개념 데이터 모델은 주요 엔터티로 한정할 뿐 논리 모델링 기법과 동일하다.","s":"2장 1절 개념 데이터 모델 의의"},
  {"id":"C4-037","ch":4,"no":37,"q":"핵심 엔터티에 대한 설명으로 가장 적절하지 않은 것은?","c":["행위의 주체나 목적물이 되는 개체 집합에 해당하는 엔터티이다","부모가 존재하지 않는 창조된 집합으로 Key Entity에 해당한다","다른 집합의 존재 유무에 상관없이 독립적으로 탄생할 수 있다","대체적으로 상위의 행위 엔터티로부터 파생되어 생성된다"],"a":3,"e":"핵심 엔터티는 부모가 존재하지 않는 창조된 집합이며, 오히려 여러 하위의 행위 엔터티를 탄생시킨다.","s":"2장 1절 개념 데이터 모델 정의"},
  {"id":"C4-038","ch":4,"no":38,"q":"데이터 모델이 제공하는 것으로 제시되지 않은 것은?","c":["다양한 영역에 집중하기 위해 다른 영역의 세부 사항은 숨기는 다양한 관점을 제공한다","시스템의 하드웨어 사양을 자동으로 산정한다","시스템을 현재 또는 원하는 모습으로 가시화하도록 도와준다","시스템의 구조와 행동을 명세화할 수 있게 한다"],"a":1,"e":"하드웨어 사양 자동 산정은 데이터 모델이 제공하는 것으로 제시되지 않았다.","s":"1장 1절 데이터 모델이 제공하는 것"},
  {"id":"C4-039","ch":4,"no":39,"q":"데이터 모델링의 재정의에 대한 설명으로 가장 적절한 것은?","c":["데이터 품질을 측정하는 기법","기업 업무에 대한 종합적인 이해를 바탕으로 데이터에 존재하는 업무 규칙에 대해 참/거짓을 판별할 수 있는 사실을, 어떻게(How)·누가(Who) 접근하는지 및 전산화와는 별개의 관점에서 명확하게 표현하는 추상화 기법","데이터베이스의 물리적 저장 구조를 결정하는 기법","프로그램의 처리 순서를 정의하는 기법"],"a":1,"e":"데이터 모델링은 업무 규칙의 참/거짓을 판별할 수 있는 사실을 접근 방법·주체·전산화와 별개의 관점에서 명확히 표현하는 추상화 기법이다.","s":"1장 1절 모델링 정의"},
  {"id":"C4-040","ch":4,"no":40,"q":"논리 데이터 모델링에 대한 설명으로 가장 적절하지 않은 것은?","c":["데이터 모델링 프로세스의 Input으로서 비즈니스 정보의 구조와 규칙을 명확하게 표현하는 기법이다","논리 데이터 모델은 데이터 모델링이 최종적으로 완료된 상태를 말한다","물리적인 스키마 설계를 하기 전 단계의 데이터 모델 상태를 일컫는다","조사·결정한 사실을 단지 ERD라는 그림으로 그려내는 과정을 말한다"],"a":3,"e":"논리 데이터 모델링은 단순히 ERD를 그리는 과정이 아니라 시스템 설계의 전 과정을 지원하는 '과정의 도구'이다.","s":"2장 1절 논리 데이터 모델 정의"},
  {"id":"C4-041","ch":4,"no":41,"q":"논리 데이터 모델링 필수 성공 요소로 제시되지 않은 것은?","c":["데이터의 구조와 무결성을 함께 고려하라","성능을 최우선으로 고려하여 반정규화를 적극 적용하라","업무에 능통한 현업 사용자와 함께 데이터 모델링을 진행하라","절차(Procedure)보다는 데이터에 초점을 두고 모델링을 진행하라"],"a":1,"e":"반정규화는 물리 데이터 모델링 단계의 활동이며, 논리 모델링 단계에서는 개념화와 정규화 기법을 적용해야 한다.","s":"2장 1절 논리 데이터 모델링 필수 성공 요소"},
  {"id":"C4-042","ch":4,"no":42,"q":"논리 데이터 모델링의 목적 및 효과로 제시되지 않은 것은?","c":["데이터베이스 접근 성능의 즉각적인 향상","해당 비즈니스에 대한 데이터 관점에서의 명확한 이해","전사적인 통합 데이터 체계 확립","데이터의 일관성 및 정확성 유지를 위한 규칙 도출"],"a":0,"e":"접근 성능 향상은 물리 데이터 모델링 및 데이터베이스 설계의 목적이다.","s":"2장 1절 논리 데이터 모델링 목적 및 효과"},
  {"id":"C4-043","ch":4,"no":43,"q":"논리 데이터 모델링 절차의 순서로 가장 적절한 것은?","c":["엔터티 정의 → 주제 영역 정의 → 속성 정의 → 관계 정의 → 정규화 → 식별자 확정 → 이력 관리","주제 영역 정의 → 속성 정의 → 엔터티 정의 → 관계 정의 → 정규화 → 이력 관리 → 식별자 확정","엔터티 정의 → 관계 정의 → 주제 영역 정의 → 식별자 확정 → 속성 정의 → 정규화 → 이력 관리","주제 영역 정의 → 엔터티 정의 → 관계 정의 → 속성 정의 → 식별자 확정 → 정규화 → 이력 관리"],"a":3,"e":"논리 데이터 모델링 절차는 주제 영역 정의 → 엔터티 정의 → 관계 정의 → 속성 정의 → 식별자 확정 → 정규화 → 이력 관리 순이다.","s":"2장 1절 논리 데이터 모델링 절차"},
  {"id":"C4-044","ch":4,"no":44,"q":"'개념화(Conceptualization)'와 '정규화(Normalization)'에 대한 설명으로 옳은 것은?","c":["개념화는 현실 세계에서 발생하는 업무 데이터를 엔터티·관계·속성으로 표현하는 추상화이고, 정규화는 데이터의 이상 현상을 제거하여 무결성과 유연성을 향상시키는 기법이다","둘 다 물리 데이터 모델링 단계의 기법이다","둘 다 반정규화를 전제로 한다","개념화는 데이터의 이상 현상을 제거하는 기법이고, 정규화는 현실 세계 데이터를 엔터티·관계·속성으로 표현하는 추상화이다"],"a":0,"e":"개념화는 추상화 과정, 정규화는 이상 현상(입력·수정·삭제 이상)을 제거하여 데이터 무결성과 유연성을 향상시키는 기법이다.","s":"2장 1절 논리 데이터 모델링 필수 성공 요소"},
  {"id":"C4-045","ch":4,"no":45,"q":"OLAP 환경에서 데이터 분석 시 중요하게 다루어지는 관점은?","c":["보안 등급 관점","물리 저장 구조 관점","네트워크 대역폭 관점","시간의 이력(History) 관점"],"a":3,"e":"OLAP 환경에서는 시간의 이력(History) 관점에서 데이터를 분석하는 것이 중요하므로 이력 관리가 중요하다.","s":"2장 1절 논리 데이터 모델링 절차"},
  {"id":"C4-046","ch":4,"no":46,"q":"관계형 데이터베이스와 비관계형 데이터베이스 모델의 비교로 옳지 않은 것은?","c":["관계형은 6가지 특성을 갖는 Table 구조이고, 비관계형은 Flat File 구조이다","관계형은 Post-Define 스키마로 DB 구조 변경이 상대적으로 쉽고, 비관계형은 Pre-Define 스키마로 변경이 어렵다","관계형은 집합(SET) 처리, 비관계형은 한 건씩(Record) 처리한다","관계형은 Key와 접근경로(Index)가 거의 동일하다"],"a":3,"e":"관계형은 Key와 접근경로(Index)가 별개의 개념이고 데이터 접근 경로가 유연하지만, 비관계형은 Key와 접근경로가 거의 동일하고 접근 경로가 제한적이다.","s":"1장 4절 관계형 비관계형 비교"},
  {"id":"C4-047","ch":4,"no":47,"q":"세그먼트(Segment)에 대한 설명으로 옳은 것은?","c":["관계형 모델의 인덱스와 같은 개념이다","관계형 모델의 뷰와 같은 개념이다","관계형 모델의 트리거와 같은 개념이다","계층형 데이터베이스 모델의 파일로 관계형 모델의 테이블과 같은 개념이다"],"a":3,"e":"세그먼트는 계층형 데이터베이스 모델의 파일로, 관계형 모델의 테이블과 같은 개념이다.","s":"1장 4절 데이터 조작"},
  {"id":"C4-048","ch":4,"no":48,"q":"계층형 데이터베이스와 관계형 데이터베이스의 데이터 처리 방식 비교로 옳은 것은?","c":["둘 다 집합 처리 방식이다","둘 다 순차 처리 방식이다","계층형은 집합 처리, 관계형은 순차 처리","계층형은 한 건씩의 레코드를 처리하는 순차 처리, 관계형은 속성의 원자값에 의한 집합 처리"],"a":3,"e":"계층형은 파일 포인터를 이용한 순차 처리, 관계형은 원자값에 의한 집합 처리 방식이다.","s":"1장 4절 데이터 조작"},
  {"id":"C4-049","ch":4,"no":49,"q":"IBM의 IMS DB와 관련한 초기 정보시스템 설계 방법에 대한 설명으로 옳은 것은?","c":["엔터티-관계도(ERD)를 중심으로 데이터 중심의 설계를 하였다","객체지향 방법론으로 UML을 사용하였다","컴포넌트 기반 방법론으로 J2EE를 사용하였다","데이터보다는 프로세스와 기능 위주의 구조적 방법론과 데이터 흐름도(DFD)를 사용하였다"],"a":3,"e":"당시에는 프로세스·기능 위주의 구조적 방법론과 DFD를 사용하여 정보의 고립화를 초래하였다.","s":"1장 1절 데이터 모델링 탄생 배경"},
  {"id":"C4-050","ch":4,"no":50,"q":"데이터 모델링 탄생 배경에서 데이터베이스 기술이 제공한 이점으로 제시된 것은?","c":["네트워크 대역폭 절감","사용자 인터페이스 개선","보안 정책의 자동화","프로그램으로부터 데이터의 독립성 보장, 정보시스템 개발·유지보수의 생산성 향상"],"a":3,"e":"데이터베이스 기술은 프로그램으로부터 데이터의 독립성을 보장하고 개발·유지보수의 생산성을 향상시켰다.","s":"1장 1절 데이터 모델링 탄생 배경"},
  {"id":"C4-051","ch":4,"no":51,"q":"(2020 Edition) 데이터 모델의 정의로 제시된 것은?","c":["데이터베이스 설계에 대한 계획 또는 청사진","현실 세계의 추상화된 반영","데이터베이스 생성을 위한 업무 규칙과 정보의 구조를 표현하는 기법","현실 세계에 대해 우리가 관심있어 하는 대상을 데이터베이스화하기 위한 개념적 도구"],"a":2,"e":"2013 Edition은 '관심 대상을 데이터베이스화하기 위한 개념적 도구', 2020 Edition은 '데이터베이스 생성을 위한 업무 규칙과 정보의 구조를 표현하는 기법'으로 정의한다.","s":"1장 1절 모델 정의"},
  {"id":"C4-052","ch":4,"no":52,"q":"릴레이션(Relation)의 수학적 정의로 가장 적절한 것은?","c":["주어진 도메인들의 교집합","주어진 도메인들의 차집합","주어진 도메인들의 카티션 프로덕트(Cartesian Product)의 부분집합","주어진 도메인들의 합집합"],"a":2,"e":"릴레이션은 주어진 도메인들의 카티션 프로덕트의 부분집합으로 정의된다.","s":"1장 4절 릴레이션 개념"},
  {"id":"C4-053","ch":4,"no":53,"q":"릴레이션 관련 용어의 대응이 옳지 않은 것은?","c":["애트리뷰트 - 속성 - 칼럼 - 필드","Degree - 튜플의 수 / Cardinality - 애트리뷰트의 개수","릴레이션 - 엔터티 - 테이블 - 파일","튜플(Tuple) - 인스턴스 - 로우 - 레코드"],"a":1,"e":"Degree는 애트리뷰트의 개수, Cardinality는 튜플(Row)의 수이다.","s":"1장 4절 릴레이션 개념"},
  {"id":"C4-054","ch":4,"no":54,"q":"Relation Schema와 Relation Instance에 대한 설명으로 옳은 것은?","c":["Instance는 릴레이션의 논리적 구조로 정적 성격을 갖는다","Schema와 Instance 모두 동적 성격을 갖는다","Schema는 릴레이션의 논리적 구조로 시간에 따라 변하지 않는 정적 성격을 갖는다","Schema는 어느 한 시점의 릴레이션의 내용으로 동적 성격을 갖는다"],"a":2,"e":"Schema는 논리적 구조로 정적(시간에 따라 변하지 않음), Instance는 어느 한 시점의 내용으로 동적(생성·소멸)이다.","s":"1장 4절 릴레이션 개념"},
  {"id":"C4-055","ch":4,"no":55,"q":"관계형 모델 릴레이션의 6가지 특성에 해당하지 않는 것은?","c":["각 열은 유일한 이름을 갖는다","각 열은 하나의 값을 가진다","각 행은 유일하다","열의 순서는 의미가 있다"],"a":3,"e":"열의 순서는 의미가 없다(애트리뷰트의 무순서성). 행의 순서도 의미가 없다.","s":"1장 4절 데이터 구조"},
  {"id":"C4-056","ch":4,"no":56,"q":"'각 열은 하나의 값을 가진다'는 특성과 가장 밀접하게 관련된 것은?","c":["제1정규형(1NF)","제2정규형(2NF)","제3정규형(3NF)","BCNF"],"a":0,"e":"애트리뷰트 값으로 반복그룹이 허용되지 않는다는 것은 제1정규형 릴레이션의 조건이다.","s":"1장 4절 데이터 구조"},
  {"id":"C4-057","ch":4,"no":57,"q":"속성이 반복그룹 속성이 아닌 단일 값이면서 원자 값이어야 하는 이유로 제시되지 않은 것은?","c":["정보 접근의 유연성","테이블 구조 변경의 유연성","입력·수정·삭제 이상 현상을 없애고 데이터 무결성 확보","인덱스 저장 공간의 절감"],"a":3,"e":"제시된 이유는 정보 접근의 유연성, 테이블 구조 변경의 유연성, 이상 현상 제거를 통한 무결성 확보이다.","s":"1장 4절 데이터 구조"},
  {"id":"C4-058","ch":4,"no":58,"q":"'각 열의 값은 동일한 종류이다'라는 특성과 직접 관련된 무결성은?","c":["참조무결성","도메인 무결성","연쇄작용","엔터티 무결성"],"a":1,"e":"릴레이션 내 각 애트리뷰트의 값이 동일한 종류로 정의되어야 한다는 것은 도메인 무결성이다.","s":"1장 4절 데이터 구조"},
  {"id":"C4-059","ch":4,"no":59,"q":"'각 열은 유일한 이름을 갖는다'는 특성에 대한 설명으로 옳은 것은?","c":["스키마 내에서 유일해야 한다","열이 표현되는 테이블 내에서 유일하면 되며, DBMS 전체나 데이터베이스에서 유일할 필요는 없다","DBMS 전체에서 유일해야 한다","데이터베이스 내에서 유일해야 한다"],"a":1,"e":"열 이름은 해당 테이블 내에서 유일해야 하며, DBMS 전체나 데이터베이스에서 유일할 필요는 없다.","s":"1장 4절 데이터 구조"},
  {"id":"C4-060","ch":4,"no":60,"q":"관계형 모델 이론의 3가지 기초 영역으로 옳게 묶인 것은?","c":["데이터 구조, 데이터 조작, 데이터 무결성","데이터 정의, 데이터 제어, 데이터 조작","엔터티, 관계, 속성","개념, 논리, 물리"],"a":0,"e":"관계형 모델 이론은 데이터 구조(Structure), 데이터 조작(Manipulation), 데이터 무결성(Integrity)에 대한 기초와 배경을 제공한다.","s":"1장 4절 관계형 모델 이론"},
  {"id":"C4-061","ch":4,"no":61,"q":"E.F. Codd 박사가 관계형 데이터베이스 모델의 이론적 배경으로 삼은 두 분야로 옳은 것은?","c":["집합이론(Set Theory)과 1차 술어 논리(1st Predicate Logic)","그래프 이론과 확률론","선형대수와 미적분학","정보이론과 부호이론"],"a":0,"e":"E.F. Codd는 수학의 집합이론과 1차 술어 논리를 이론적 배경으로 관계형 데이터베이스 모델을 제작하였다.","s":"1장 4절 관계형 모델 이론"},
  {"id":"C4-062","ch":4,"no":62,"q":"관계 연산자(조회)에 해당하지 않는 것은?","c":["Division","Update","Select(Restrict)","Project"],"a":1,"e":"Update는 처리 연산자(Insert, Update, Delete)에 해당한다.","s":"1장 4절 데이터 조작"},
  {"id":"C4-063","ch":4,"no":63,"q":"관계 연산자에 대한 설명으로 옳지 않은 것은?","c":["Select(Restrict)는 열에 의거한 행의 부분집합이다","Project는 열의 부분집합이다","Union은 중복을 없이하여 각 행을 수직적으로 묶는다","Difference는 두 관계 테이블 간의 공통된 행이다"],"a":3,"e":"두 관계 테이블 간의 공통된 행은 Intersection이며, Difference는 하나의 관계 테이블에만 있는 행이다.","s":"1장 4절 데이터 조작"},
  {"id":"C4-064","ch":4,"no":64,"q":"관계 연산자 'Division'에 대한 설명으로 가장 적절한 것은?","c":["두 관계 테이블 간 행의 조합을 묶음","열의 기준에 의거하여 각 행을 수평적으로 묶음","하나의 관계 테이블에만 있는 행","다른 관계 테이블의 모든 행에 대응하는 열을 제외한 열"],"a":3,"e":"Division은 다른 관계 테이블의 모든 행에 대응하는 열을 제외한 열을 구하는 연산이다.","s":"1장 4절 데이터 조작"},
  {"id":"C4-065","ch":4,"no":65,"q":"데이터 무결성 규칙 4가지에 해당하지 않는 것은?","c":["도메인(속성) 무결성 규칙","저장 무결성 규칙","엔터티 무결성 규칙","참조 무결성 규칙"],"a":1,"e":"데이터 무결성은 엔터티 무결성, 참조 무결성, 도메인(속성) 무결성 규칙 및 연쇄작용(업무 규칙)으로 구성된다.","s":"1장 4절 데이터 무결성"},
  {"id":"C4-066","ch":4,"no":66,"q":"식별자가 널(NULL) 값을 허용하지 않는 이유에 대한 설명으로 가장 적절한 것은?","c":["Null 값은 조인이 되지 않아 원래의 행을 조회할 수 없게 되어 무결성이 깨지기 때문이다","Null 값은 저장 공간을 많이 차지하기 때문이다","Null 값은 인덱스 크기를 증가시키기 때문이다","Null 값은 정렬 순서를 결정할 수 없기 때문이다"],"a":0,"e":"PK에 Null이 있으면 분해된 테이블을 조인해도 원래 행을 복원할 수 없어 무결성이 깨진다.","s":"1장 4절 엔터티 무결성 규칙"},
  {"id":"C4-067","ch":4,"no":67,"q":"식별자가 유일해야 하는 이유에 대한 설명으로 가장 적절한 것은?","c":["식별자 값의 정렬이 불가능하기 때문이다","외래키 제약을 생성할 수 없기 때문이다","분해된 테이블을 조인할 때 원래 없던 행이 조회되는 다대다 곱집합(Product)이 발생하기 때문이다","식별자 컬럼의 인덱스 크기가 커지기 때문이다"],"a":2,"e":"식별자가 유일하지 않으면 분해 후 조인 시 원래 없던 행이 생기는 카티션 프로덕트가 발생한다.","s":"1장 4절 엔터티 무결성 규칙"},
  {"id":"C4-068","ch":4,"no":68,"q":"주 키(PK) 선정 기준으로 제시되지 않은 것은?","c":["저장 공간을 가장 적게 차지하는 것","주 키를 구성하는 각각의 칼럼 수를 최소한의 집합으로 할 것","값의 수정이 없는 것","업무적으로 활용도가 높은 것"],"a":0,"e":"PK 선정 기준은 최소한의 칼럼 집합, 값의 수정이 없는 것, 업무적 활용도가 높은 것이다.","s":"1장 4절 엔터티 무결성 규칙"},
  {"id":"C4-069","ch":4,"no":69,"q":"식별자가 최소한의 속성 집합으로 구성되어야 하는 이유로 가장 적절한 것은?","c":["최소한의 속성 집합이 아니면 유일 식별자의 유일성이 깨질 수 있기 때문이다","저장 공간을 절약하기 위해서이다","조인 성능을 향상시키기 위해서이다","외래키 상속을 줄이기 위해서이다"],"a":0,"e":"유일성은 어떤 다른 속성을 합쳐도 유일하므로, 최소한의 속성 집합이 아니면 실제로는 유일성이 깨진 상태를 감출 수 있다.","s":"1장 4절 엔터티 무결성 규칙"},
  {"id":"C4-070","ch":4,"no":70,"q":"참조 무결성 규칙에 대한 설명으로 가장 적절한 것은?","c":["외래 키는 반드시 Null 값을 허용해야 한다","외래 키는 부모 엔터티의 일반 속성을 참조해야 한다","참조 무결성은 데이터베이스 설계 관점에서 임의로 선택하면 된다","엔터티(테이블)의 모든 외래 키 값은 관계있는 엔터티에 주 키 값으로 존재해야 한다"],"a":3,"e":"참조 무결성 규칙은 모든 외래 키 값이 관계있는 엔터티의 주 키 값으로 존재해야 한다는 것이며, 현업의 업무 규칙에 따라 적절한 규칙을 선택해야 한다.","s":"1장 4절 참조무결성 규칙"},
  {"id":"C4-071","ch":4,"no":71,"q":"참조무결성 입력 규칙 중 'Dependent'에 대한 설명으로 옳은 것은?","c":["대응되는 부모 실체에 인스턴스가 있는 경우에만 자식 실체에 입력을 허용한다","자식 실체 인스턴스의 입력을 항상 허용하고 대응되는 부모 건이 없는 경우 이를 자동 생성한다","대응되는 부모 건이 없는 경우 자식 실체의 참조키를 Null 처리한다","자식 실체 인스턴스의 입력을 조건 없이 허용한다"],"a":0,"e":"2번은 Automatic, 3번은 Nullify, 4번은 No Effect이다.","s":"1장 4절 참조무결성 규칙"},
  {"id":"C4-072","ch":4,"no":72,"q":"참조무결성 삭제 규칙 중 'Cascade'에 대한 설명으로 옳은 것은?","c":["대응되는 자식 실체의 인스턴스가 없는 경우에만 부모 실체 인스턴스 삭제를 허용한다","부모 실체 인스턴스의 삭제를 항상 허용하고 대응되는 자식 실체의 인스턴스를 자동 삭제한다","대응되는 자식 실체의 인스턴스가 존재하면 그것의 참조키를 Null 값으로 수정한다","특정한 검증 조건이 만족되는 경우에만 부모 실체 인스턴스의 삭제를 허용한다"],"a":1,"e":"1번은 Restrict, 3번은 Nullify, 4번은 Customized이다.","s":"1장 4절 참조무결성 규칙"},
  {"id":"C4-073","ch":4,"no":73,"q":"참조무결성 삭제 규칙 중 'set null'에 대한 설명으로 옳은 것은?","c":["자식 테이블에서 참조하는 경우 부모 테이블의 값 삭제가 불가하다","참조하고 있는 자식 테이블의 값도 함께 삭제한다","참조하고 있는 자식 테이블의 값을 null로 바꾼다","참조하고 있는 자식 테이블의 값을 미리 지정해 놓은 값으로 변경한다"],"a":2,"e":"1번은 restrict, 2번은 cascade, 4번은 set default이다.","s":"1장 4절 참조무결성 규칙"},
  {"id":"C4-074","ch":4,"no":74,"q":"도메인 무결성 규칙에 포함되는 제한 사항으로 가장 거리가 먼 것은?","c":["데이터 타입, 길이","허용 값, 기본값","유일성, 널(Null) 여부","부모 엔터티 존재 여부"],"a":3,"e":"부모 엔터티 존재 여부는 참조무결성의 영역이다.","s":"1장 4절 도메인 무결성 규칙"},
  {"id":"C4-075","ch":4,"no":75,"q":"도메인의 중요성에 대한 설명으로 가장 적절하지 않은 것은?","c":["속성 정의 시 도메인을 함께 명세함으로써 DBMS가 값의 적정성을 검사할 수 있다","도메인은 논리 데이터 모델에서는 정의하지 않고 물리 설계 시에만 정의한다","도메인의 어떤 특정 값이 결정될 때 이 값을 보고 의사 결정을 한다","같은 도메인의 값들끼리 비교가 허용된다"],"a":1,"e":"도메인은 데이터베이스 정의의 한 부분으로 분명하게 정의되어 속성이 취할 수 있는 값을 제한하며, 논리 모델링 단계부터 정의된다.","s":"1장 4절 도메인 무결성 규칙"},
  {"id":"C4-076","ch":4,"no":76,"q":"연쇄 작용(Triggering Operation)에 대한 설명으로 가장 적절한 것은?","c":["외래 키 제약 조건을 데이터베이스에 물리적으로 설정하는 것","도메인의 허용 값을 제한하는 것","식별자의 유일성을 보장하는 것","입력·수정·삭제·조회 등의 작업이 동일 엔터티 혹은 다른 엔터티의 속성에 영향을 미치는 업무 규칙을 정의하는 것"],"a":3,"e":"연쇄 작용은 입력·수정·삭제·조회 작업이 동일 또는 다른 엔터티의 속성에 영향을 미치는 업무 규칙을 정의하는 것이다.","s":"1장 4절 연쇄 작용"},
  {"id":"C4-077","ch":4,"no":77,"q":"연쇄 작용 정의 시 도출해야 할 항목으로 제시되지 않은 것은?","c":["실행 계획, 인덱스 구성","사용자 규칙, 사건(INSERT/UPDATE/DELETE/SELECT)","엔터티, 속성","조건, 연쇄작용"],"a":0,"e":"연쇄 작용 정의 항목은 사용자 규칙, 사건, 엔터티, 속성, 조건, 연쇄작용이다.","s":"1장 4절 연쇄 작용"},
  {"id":"C4-078","ch":4,"no":78,"q":"연쇄작용 유형 중 '유형 2'에 해당하는 것은?","c":["시점에 의해 자동으로 일어나는 연쇄작용(일 마감작업)","개체타입 간의 관계에 따른 무결성 유지의 필요성을 정의한 연쇄작용","사용자 규칙에 의한 연쇄작용(납기일은 주문일로부터 3일 이후여야 한다)","Source 속성값의 변화에 따른 유도 속성값의 변화를 정의(주문.주문총액)"],"a":3,"e":"유형 1은 사용자 규칙, 유형 2는 유도 속성값 변화, 유형 3은 시점 자동, 유형 4는 관계에 따른 무결성 유지이다.","s":"1장 4절 연쇄작용 유형"},
  {"id":"C4-079","ch":4,"no":79,"q":"양쪽 필수 관계에서 자식 엔터티의 마지막 행이 삭제될 때의 처리로 가장 적절한 것은?","c":["아무 처리도 필요 없다","부모 엔터티도 같이 삭제하거나 마지막 자식의 삭제를 취소한다","자식만 삭제하고 부모는 그대로 둔다","부모의 외래키를 Null로 변경한다"],"a":1,"e":"양쪽 필수 관계에서는 해당 주문건의 마지막 주문상품을 삭제하면 해당 주문을 함께 삭제하거나 마지막 주문상품의 삭제를 취소해야 한다.","s":"1장 4절 연쇄작용 유형"},
  {"id":"C4-080","ch":4,"no":80,"q":"외래키 제약 조건(Foreign Key Constraint) 설정에 대한 설명으로 가장 적절한 것은?","c":["반드시 데이터베이스에 물리적으로 설정해야 한다","반드시 프로그램으로만 구현해야 한다","외래키 제약은 성능에 영향을 주지 않으므로 항상 설정한다","설계 단계에서 성능과 데이터 무결성을 고려하여 데이터베이스에 물리적으로 설정할지 프로그램으로 해결할지 결정한다"],"a":3,"e":"설계 단계에서 성능과 데이터 무결성을 고려하여 물리적 설정 여부 또는 프로그램 처리 여부를 결정한다.","s":"1장 4절 참조무결성 규칙"},
  {"id":"C4-081","ch":4,"no":81,"q":"현행에서 목표 데이터베이스로 데이터 이행 시 참조무결성이 깨져 있는 데이터에 대한 처리로 가장 적절한 것은?","c":["이행을 중단하고 현행 시스템을 유지한다","어떤 기본 값(Default Value)을 설정하여 해결하고, 목표 데이터베이스에서는 참조무결성이 깨지지 않도록 관리한다","깨진 데이터를 모두 삭제한다","참조무결성 제약을 해제한 채로 운영한다"],"a":1,"e":"참조무결성이 깨져 있는 데이터는 기본 값을 설정하여 해결하고 목표 DB에서는 무결성이 깨지지 않도록 관리한다.","s":"1장 4절 참조무결성 규칙"},
  {"id":"C4-082","ch":4,"no":82,"q":"애트리뷰트(속성) 값에 대한 설명으로 가장 적절한 것은?","c":["데이터의 물리적 저장 단위이다","반드시 숫자형이어야 한다","여러 개의 값을 가질 수 있다","관계형 모델에서 데이터의 가장 작은 논리적 단위로, 의미를 갖는 더 이상 분해할 필요가 없는 원자값이다"],"a":3,"e":"애트리뷰트 값은 데이터의 가장 작은 논리적 단위로 더 이상 분해할 필요가 없는 원자값(Atomic Value)이다.","s":"1장 4절 속성과 도메인의 개념"},
  {"id":"C4-083","ch":4,"no":83,"q":"반복 그룹(Repeating Group) 속성을 가진 비정규화된 테이블의 문제점으로 가장 적절한 것은?","c":["조인이 불가능해진다","입력·수정·삭제 이상 현상이 발생하여 데이터의 일관성과 정확성이 깨진다","저장 공간이 크게 증가한다","인덱스를 생성할 수 없다"],"a":1,"e":"반복그룹 속성을 가진 비정규화 테이블은 입력·수정·삭제 이상 현상이 발생하여 데이터의 일관성·정확성이 깨진다.","s":"1장 4절 데이터 구조"},
  {"id":"C4-084","ch":4,"no":84,"q":"관계형 모델의 처리 방식과 파일 처리 방식의 차이에 대한 설명으로 옳은 것은?","c":["두 방식은 처리 결과가 항상 다르다","순차 처리 방식은 파일 포인터를 이용해 레코드를 한 건씩 처리하고, 집합 처리 방식은 전체집합에서 부분집합을 구하는 SQL 문으로 처리한다","순차 처리 방식이 집합 처리 방식보다 항상 빠르다","집합 처리 방식은 원자값이 아니어도 처리 가능하다"],"a":1,"e":"순차 처리는 파일 포인터로 한 건씩, 집합 처리는 전체집합에서 부분집합을 구하는 SQL로 처리한다.","s":"1장 4절 데이터 구조"},
  {"id":"C4-085","ch":4,"no":85,"q":"where절에 기술한 속성의 단위가 원자 값이어야 하는 이유로 가장 적절한 것은?","c":["집합 처리 방식에서 조건을 만족하는 부분집합을 정확히 구하기 위해서이다","인덱스를 생성하기 위해서이다","저장 공간을 절약하기 위해서이다","트랜잭션 잠금을 줄이기 위해서이다"],"a":0,"e":"관계형 모델의 집합 처리 방식에서 where절 조건 속성이 원자값이어야 부분집합을 정확히 구할 수 있다.","s":"1장 4절 데이터 구조"},
  {"id":"C4-086","ch":4,"no":86,"q":"관계형 모델이 지향하는 '단순성'에 대한 설명으로 가장 적절한 것은?","c":["테이블 개수를 최소화한다는 의미이다","속성 개수를 최소화한다는 의미이다","SQL 문법이 단순하다는 의미이다","약간의 친숙한 개념들을 사용하여 모델을 묘사할 수 있음을 의미한다"],"a":3,"e":"관계형 모델의 단순성은 약간의 친숙한 개념들을 사용하여 모델을 묘사할 수 있음을 의미한다.","s":"1장 4절 관계형 모델 이론"},
  {"id":"C4-087","ch":4,"no":87,"q":"데이터 무결성 보장 주체에 대한 설명으로 가장 적절한 것은?","c":["될 수 있으면 프로그램의 로직이 아니라 데이터베이스 시스템이 데이터 무결성을 보장하도록 하는 것이 바람직하다","반드시 프로그램 로직으로만 보장해야 한다","반드시 데이터베이스로만 보장해야 한다","무결성은 사용자가 직접 확인해야 한다"],"a":0,"e":"될 수 있으면 프로그램 로직이 아니라 DBMS가 데이터 무결성을 보장하도록 하고, 논리 모델링 과정에서 업무 규칙을 정확히 기술한 후 시스템 설계 과정에서 처리 방법을 결정한다.","s":"1장 4절 관계형 모델 이론"},
  {"id":"C4-088","ch":4,"no":88,"q":"Oracle에서 데이터 무결성을 보장하기 위해 사용되는 수단으로 제시되지 않은 것은?","c":["외래 키(Foreign Key) 제약","체크(Check) 제약 및 NOT NULL 제약","파티션(Partition) 정의","기본 키(PK) 제약"],"a":2,"e":"파티션은 성능·관리 목적의 저장 구조이며 무결성 보장 수단으로 제시되지 않았다.","s":"1장 4절 관계형 모델 이론"},
  {"id":"C4-089","ch":4,"no":89,"q":"관계형 데이터 모델에서 도메인(Domain)의 정의로 가장 적절한 것은?","c":["하나의 애트리뷰트(속성)가 갖는 같은 타입의 모든 원자 값들의 집합","릴레이션의 모든 튜플의 집합","엔터티의 모든 인스턴스의 집합","관계의 모든 페어링의 집합"],"a":0,"e":"도메인은 하나의 속성이 갖는 같은 종류(타입)의 모든 원자 값들의 집합이다.","s":"1장 4절 속성과 도메인의 개념"},
  {"id":"C4-090","ch":4,"no":90,"q":"도메인의 종류에 대한 설명으로 옳은 것은?","c":["사용자 정의 도메인만 존재한다","도메인은 DBMS가 자동 생성하며 사용자가 정의할 수 없다","시스템 정의 도메인(문자·날짜·숫자 등)과 사용자 정의 도메인(예: 상태코드)이 있다","시스템 정의 도메인만 존재한다"],"a":2,"e":"도메인에는 시스템이 제공하는 시스템 정의 유형 도메인과 사용자 정의 유형 도메인이 있다.","s":"1장 2절 속성과 도메인"},
  {"id":"C4-091","ch":4,"no":91,"q":"'각 속성은 어느 한 도메인 상에서 정의되어야 한다'는 원칙의 의미로 가장 적절한 것은?","c":["도메인은 물리 설계 시에만 의미가 있다","정의된 속성은 반드시 그 해당 도메인으로부터만 값을 취할 수 있다","속성은 여러 도메인의 값을 자유롭게 취할 수 있다","도메인은 속성마다 새로 만들어야 한다"],"a":1,"e":"각 속성은 어느 한 도메인 상에서 정의되어야 하고, 정의된 속성은 반드시 그 도메인으로부터만 값을 취할 수 있다.","s":"1장 2절 속성과 도메인"},
  {"id":"C4-092","ch":4,"no":92,"q":"입력 규칙(Insert Rule) 중 'restrict'에 대한 설명으로 옳은 것은?","c":["자식 테이블에서 행을 입력할 때 부모 테이블에 없는 값을 사용하면 튜플 삽입이 불가하다","그것을 참조하고 있는 자식 테이블의 값을 그대로 유지한다","부모 테이블에 없는 값이면 부모를 자동 생성한다","입력을 조건 없이 허용한다"],"a":0,"e":"입력 규칙 restrict는 부모 테이블에 없는 값을 자식 테이블에 입력할 수 없도록 제한한다.","s":"1장 4절 참조무결성 규칙"},
  {"id":"C4-093","ch":4,"no":93,"q":"부모 엔터티와 자식 엔터티의 구분 기준으로 옳은 것은?","c":["업무적으로 먼저 발생하는 엔터티가 부모 엔터티이다","데이터 건수가 많은 엔터티가 자식 엔터티이다","속성 개수가 많은 엔터티가 부모 엔터티이다","외래 키가 나타나는 엔터티가 자식 엔터티, 주키를 외래 키로 전이시켜주는 엔터티가 부모 엔터티이다"],"a":3,"e":"데이터 모델 관점에서 외래 키가 있는 곳이 자식 엔터티이며, 업무 발생 순서와는 다를 수 있다(예: 결제-납품).","s":"1장 4절 참조무결성 / 2장 4절 관계 개념"},
  {"id":"C4-094","ch":4,"no":94,"q":"'결제 - 납품' 관계 사례에 대한 설명으로 옳은 것은?","c":["두 엔터티는 관계를 가질 수 없다","업무 관점에서는 납품이 먼저 발생하지만, 데이터 모델 관점에서는 결제의 주키가 납품에 외래 키로 나타나므로 결제가 부모이다","업무 관점과 데이터 모델 관점이 항상 일치하므로 납품이 부모이다","납품의 주키가 결제에 외래키로 나타난다"],"a":1,"e":"업무 발생 순서(납품 후 결제)와 데이터 모델의 부모·자식 관계(결제가 부모)는 다를 수 있다.","s":"2장 4절 관계 개념"},
  {"id":"C4-095","ch":4,"no":95,"q":"관계형 모델에서 릴레이션 R의 인스턴스에 대한 정의로 옳은 것은?","c":["어느 한 시점에 릴레이션 R에 포함되어 있는 튜플의 집합","릴레이션 R의 애트리뷰트 이름의 집합","릴레이션 R의 도메인의 집합","릴레이션 R의 제약조건의 집합"],"a":0,"e":"릴레이션 R의 인스턴스는 어느 한 시점에 릴레이션 R에 포함되어 있는 튜플(Tuple)의 집합이다.","s":"1장 4절 릴레이션 개념"},
  {"id":"C4-096","ch":4,"no":96,"q":"관계형 모델의 데이터 조작에 대한 설명으로 가장 적절한 것은?","c":["레코드 단위로 순차적으로 처리한다","포인터를 이용하여 처리한다","조회만 집합적으로 처리하고 변경은 순차 처리한다","입력·수정·삭제·조회를 집합적으로 처리한다(not one record at a time)"],"a":3,"e":"관계형 데이터 모델의 데이터 조작은 입력·수정·삭제·조회를 집합적으로 처리한다.","s":"1장 4절 데이터 조작"},
  {"id":"C4-097","ch":4,"no":97,"q":"'각 행은 유일하다'는 특성과 관련된 설명으로 옳은 것은?","c":["행의 순서가 의미를 가진다는 뜻이다","행마다 서로 다른 속성 집합을 가진다는 뜻이다","행의 크기가 모두 같아야 한다는 뜻이다","두 개의 똑같은 튜플은 한 릴레이션에 포함될 수 없으며 이는 엔터티 무결성과 관련된다"],"a":3,"e":"튜플의 유일성은 두 개의 똑같은 튜플이 한 릴레이션에 포함될 수 없다는 것으로 엔터티 무결성과 관련된다.","s":"1장 4절 데이터 구조"},
  {"id":"C4-098","ch":4,"no":98,"q":"다중값(Multi Value)을 갖는 속성에 대한 조치로 가장 적절한 것은?","c":["정규화(Normalization)를 수행해야 한다","반정규화를 수행해야 한다","인덱스를 생성해야 한다","도메인을 확장해야 한다"],"a":0,"e":"다중값을 갖는 속성은 정규화를 통해 해소해야 한다.","s":"1장 4절 데이터 구조"},
  {"id":"C4-099","ch":4,"no":99,"q":"유도(Derived) 속성 및 계산(Calculated) 속성에 대한 연쇄작용 예시로 가장 적절한 것은?","c":["고객번호, 주문번호","부서코드, 사원번호","상품명, 고객명","주문 총액, 이자"],"a":3,"e":"유도·계산 속성의 예로 주문 총액, 이자 등이 제시되며, 이는 연쇄작용 유형 2에 해당한다.","s":"1장 4절 연쇄 작용"},
  {"id":"C4-100","ch":4,"no":100,"q":"연쇄 작용 사례에서 '주문상품에 새로운 행을 입력하면 주문.주문총액을 SUM(수량*단가)으로 갱신'하는 규칙의 사건(Event)으로 옳은 것은?","c":["INSERT","UPDATE","DELETE","SELECT"],"a":0,"e":"주문상품에 새로운 행을 입력하는 것은 INSERT 사건이며, 대상 엔터티는 주문, 속성은 주문총액이다.","s":"1장 4절 연쇄 작용 사례"},
  {"id":"C4-101","ch":4,"no":101,"q":"업무 규칙의 양이 많아 논리 데이터 모델 내에 정리할 수 없을 때의 처리로 가장 적절한 것은?","c":["물리 모델링 단계로 미룬다","참고 자료를 작성하여 논리 데이터 모델과 연계성을 갖도록 한다","업무 규칙을 생략한다","모든 업무 규칙을 프로그램에만 반영한다"],"a":1,"e":"업무 규칙이 많아 모델 내에 정리할 수 없다면 참고 자료를 작성하여 논리 데이터 모델과 연계성을 갖도록 해야 한다.","s":"1장 4절 연쇄 작용"},
  {"id":"C4-102","ch":4,"no":102,"q":"관계형 모델에서 'Product' 연산에 대한 설명으로 옳은 것은?","c":["두 관계 테이블 간 행의 조합을 묶는 연산이다","열의 기준에 의거하여 각 행을 수평적으로 묶는 연산이다","중복을 없이하여 각 행을 수직적으로 묶는 연산이다","하나의 관계 테이블에만 있는 행을 구하는 연산이다"],"a":0,"e":"Product는 두 관계 테이블 간 행의 조합을 묶는 연산이며, 2번은 Join, 3번은 Union, 4번은 Difference이다.","s":"1장 4절 데이터 조작"},
  {"id":"C4-103","ch":4,"no":103,"q":"주제 영역(Subject Area)에 대한 설명으로 가장 적절하지 않은 것은?","c":["하나의 주제 영역 내 엔터티 간의 관계는 밀접하고 다른 주제 영역 엔터티와의 상호작용은 최소화되도록 정의한다","계획 수립 단계는 상향식 분석을 원칙으로 하고 검증을 위해 부분적으로 하향식 분석을 사용한다","주제 영역은 계층적으로 표현 가능하며 분해하면 하위 수준의 주제 영역이나 엔터티가 나타난다","주요 자원·상품·활동을 중심으로 조직이 관심을 가지는 영역으로 조직이 사용하는 데이터의 최상위 집합이다"],"a":1,"e":"계획 수립 단계는 하향식 분석을 원칙으로 하고 검증을 위해 부분적으로 상향식 분석을 사용한다.","s":"2장 2절 주제 영역 개념"},
  {"id":"C4-104","ch":4,"no":104,"q":"주제 영역의 특성을 나타내는 표현으로 가장 적절한 것은?","c":["Low Cohesion, Tightly Coupled","High Cohesion, Tightly Coupled","Low Cohesion, Loosely Coupled","High Cohesion, Loosely Coupled (높은 응집도, 낮은 결합도)"],"a":3,"e":"주제 영역 내부 데이터의 관계는 밀접하고(높은 응집도), 다른 주제 영역 데이터와의 상호작용은 최소화(낮은 결합도)해야 한다.","s":"2장 2절 주제 영역 개념"},
  {"id":"C4-105","ch":4,"no":105,"q":"주제 영역 분류 원칙으로 제시되지 않은 것은?","c":["데이터 확장성 보장","데이터 관련성 및 편의성 확보","데이터 접근 성능 최적화","데이터 중복 최소화"],"a":2,"e":"주제 영역 분류 원칙은 데이터 중복 최소화, 데이터 확장성 보장, 데이터 관련성 및 편의성 확보이다.","s":"2장 2절 주제 영역 분류 원칙 및 기준"},
  {"id":"C4-106","ch":4,"no":106,"q":"주제 영역 분류 기준 중 '데이터 관점의 분류'에 대한 설명으로 가장 적절한 것은?","c":["시스템별로 분류한다","화면·보고서 단위로 분류한다","업무를 발생시키는 주체·대상(키 엔터티) 및 행위(액션 엔터티) 등 데이터를 생성·사용하는 유형에 근거하여 분류한다","조직도의 부서 단위에 따라 분류한다"],"a":2,"e":"데이터 관점의 분류는 데이터를 생성·사용하는 유형에 근거하며, 장기적·전사적 관점에서 데이터 유사성을 고려한다.","s":"2장 2절 주제 영역 분류 기준"},
  {"id":"C4-107","ch":4,"no":107,"q":"주제 영역 명명 원칙으로 옳지 않은 것은?","c":["데이터 그룹을 의미하는 용어를 사용한다","업무 활동을 의미하는 이름(예: 재무관리, 인사관리)을 사용한다","실 업무에서 사용하는 보편적 용어를 사용한다","단수형 명사를 사용한다"],"a":1,"e":"업무 활동을 의미하는 이름은 배제하고 데이터 그룹을 의미하는 이름(재무 분야, 인사 분야)을 사용한다.","s":"2장 2절 주제 영역 명명"},
  {"id":"C4-108","ch":4,"no":108,"q":"주제 영역 도출 방법에 해당하지 않는 것은?","c":["데이터베이스 실행 계획으로부터 도출","업무 기능의 이름으로부터 도출","업무에서 사용하는 데이터의 명사형 도출","하향식(Top-Down) 접근 방법과 상향식(Bottom-Up) 접근 방법"],"a":0,"e":"주제 영역 도출 방법은 업무 기능명, 데이터 명사형, 하향식·상향식 접근, 분석 단계에서의 도출이다.","s":"2장 2절 주제 영역 도출"},
  {"id":"C4-109","ch":4,"no":109,"q":"주제 영역 활용 목적으로 제시되지 않은 것은?","c":["기업의 전사 업무를 위한 전체 데이터 구성에 대한 청사진 제공","데이터베이스 파티션 키 결정 기준 제공","데이터의 계층적 구조 파악에 도움","업무 기능과 병행 분석 시 분석의 최상위 단위 역할을 하여 품질 확보에 기여"],"a":1,"e":"파티션 키 결정은 물리 설계 영역이며 주제 영역 활용 목적으로 제시되지 않았다.","s":"2장 2절 주제 영역 활용"},
  {"id":"C4-110","ch":4,"no":110,"q":"주제 영역 활용의 장점으로 제시되지 않은 것은?","c":["데이터 및 업무 활동 모델의 품질 보증","프로젝트 관리 - 업무 범위에 대한 기준 확보","모델 개발 조정 및 리포지터리 관리 용이","SQL 실행 계획 최적화"],"a":3,"e":"SQL 실행 계획 최적화는 주제 영역 활용의 장점이 아니다.","s":"2장 2절 주제 영역 활용"},
  {"id":"C4-111","ch":4,"no":111,"q":"주제 영역 목록에 포함되는 항목으로 제시되지 않은 것은?","c":["레벨(주제 영역의 계층 수준)","주제 영역명","대표 엔터티","예상 데이터 건수"],"a":3,"e":"주제 영역 목록의 항목은 레벨, 주제 영역명, 설명(단위 주제 영역의 경우), 대표 엔터티이다.","s":"2장 2절 주제 영역 정의 내용"},
  {"id":"C4-112","ch":4,"no":112,"q":"'Divide and Conquer(분할 후 정복)'에 대한 설명으로 가장 적절한 것은?","c":["전체 업무를 점차적으로 세분화해 나가면서 정해진 규칙을 이용하여 모델링하는 것으로 세분화 과정을 분해(Decomposition)라 한다","여러 개의 모델을 통합하는 과정이다","엔터티를 물리 테이블로 변환하는 과정이다","정규화를 역으로 수행하는 과정이다"],"a":0,"e":"Divide and Conquer는 전체 업무를 점차 세분화하며 모델링하는 것이며 세분화 과정을 분해(Decomposition)라 한다.","s":"2장 2절 주제 영역 개념"},
  {"id":"C4-113","ch":4,"no":113,"q":"엔터티의 일반적 분류에 대한 설명으로 옳지 않은 것은?","c":["개념(Concept) 엔터티 - 관리할 정보가 있는 무형의 개념(계정과목, 성적 등)","종속(Dependent) 엔터티 - 물리적으로 존재하지 않는 추상적 대상","유형(Tangible) 엔터티 - 물리적으로 존재하는 대상(고객, 상품 등)","활동(Active) 엔터티 - 어떤 사건에 관한 정보(주문, 계약, 장비 고장 등)"],"a":1,"e":"종속 엔터티는 모델 관점의 분류로, 인스턴스 식별에 다른 인스턴스에 의존하는 엔터티이다.","s":"2장 3절 엔터티 분류"},
  {"id":"C4-114","ch":4,"no":114,"q":"발생 시점에 따른 엔터티 분류에서 '메인 엔터티'에 대한 설명으로 가장 적절한 것은?","c":["업무 행위의 주체나 목적어가 되며 자신의 부모를 가지지 않는 엔터티","키 엔터티가 행위를 함으로써 발생되는 행위의 집합 중 좀 더 하위의 행위를 발생시키는 주체나 목적어가 될 수 있는 엔터티","키 엔터티와 메인 엔터티가 아닌 모든 엔터티","다른 부분집합과 구별되는 공통 속성을 공유하는 부분집합"],"a":1,"e":"1번은 키 엔터티, 3번은 액션 엔터티, 4번은 서브타입 엔터티이다.","s":"2장 3절 발생 시점 엔터티 분류"},
  {"id":"C4-115","ch":4,"no":115,"q":"액션 엔터티의 예시로 가장 적절한 것은?","c":["사원, 부서, 고객, 상품, 자재","보험계약, 사고, 예금원장, 청구","상태 이력, 차량 수리 내역, 상세 주문 내역","개인고객, 법인고객"],"a":2,"e":"1번은 키 엔터티, 2번은 메인 엔터티, 4번은 서브타입 엔터티의 예이다.","s":"2장 3절 발생 시점 엔터티 분류"},
  {"id":"C4-116","ch":4,"no":116,"q":"액션 엔터티의 특징에 대한 설명으로 가장 적절한 것은?","c":["상위 엔터티들이 어떻게 결정되느냐에 따라 크게 영향을 받아 최초에 예상했던 의미상의 주어가 크게 달라질 수 있다","부모 엔터티 없이도 독립적으로 생성 가능하다","항상 키 엔터티보다 먼저 정의된다","서브타입을 가질 수 없다"],"a":0,"e":"액션 엔터티는 상위 엔터티 결정에 따라 크게 영향을 받으며, 업무 본질은 살아 있지만 의미상 주어가 크게 달라질 수 있다.","s":"2장 3절 발생 시점 엔터티 분류"},
  {"id":"C4-117","ch":4,"no":117,"q":"현행 데이터베이스를 정밀 분석해야 하는 이유로 제시되지 않은 것은?","c":["현행 DB의 라이선스 비용을 산정하기 위해","현행 DB가 조직의 정보 요구 사항을 빠짐없이 정확하게 지원하고 있는지 확인하기 위해","현행 DB의 구조적 문제점 및 해결 방안을 도출하기 위해","목표 데이터베이스로의 데이터 이행이 필요한 경우 원천 데이터를 정확히 파악하기 위해"],"a":0,"e":"라이선스 비용 산정은 현행 DB 정밀 분석의 이유로 제시되지 않았다.","s":"2장 3절 현행 데이터베이스로부터 도출"},
  {"id":"C4-118","ch":4,"no":118,"q":"차세대 정보시스템 구축 단계에서 현행 시스템이 존재하는 경우 추가되는 단계는?","c":["계획","테스트","운영","이전(Transition, 데이터 이행 및 시스템 이전)"],"a":3,"e":"현행 시스템이 존재하는 경우 계획→분석→설계→개발→테스트→이전(Transition)→운영의 단계를 거친다.","s":"2장 3절 현행 데이터베이스로부터 도출"},
  {"id":"C4-119","ch":4,"no":119,"q":"데이터 이행 단계에 포함되지 않는 활동은?","c":["이행 매핑 정의, 이행 프로그램 개발","이행 데이터 검증·정제, 이행 테스트","목표 시스템의 화면 설계","이행 전략 수립, 이행 대상·범위 결정"],"a":2,"e":"화면 설계는 데이터 이행 단계의 활동이 아니다.","s":"2장 3절 현행 데이터베이스로부터 도출"},
  {"id":"C4-120","ch":4,"no":120,"q":"데이터 이행 일정 수립에 대한 설명으로 가장 적절한 것은?","c":["이행 리허설은 1회만 수행한다","개발자들의 프로그램 개발이 끝나기 전에 기준정보(부서, 사원, 고객, 상품 등)부터 데이터를 이행하여 대용량의 질 좋은 현행 데이터로 단위 테스트를 잘할 수 있도록 해야 한다","데이터 이행은 개발이 완전히 끝난 후 한 번에 수행해야 한다","이행 데이터 검증·정제는 운영 이행 직전에만 수행한다"],"a":1,"e":"기준정보부터 먼저 이행하여 질 좋은 현행 데이터로 단위 테스트를 지원하고, 종합 테스트 단계에서 N차에 걸쳐 이행 리허설을 수행한다.","s":"2장 3절 현행 데이터베이스로부터 도출"},
  {"id":"C4-121","ch":4,"no":121,"q":"정보 요구 범주와 사용자 특성의 연결이 옳지 않은 것은?","c":["통제(Control) - 하급관리자 - 단기 관점(일, 주간), 프로세스 관점, 실적 데이터, 정규보고 정보","운영(Operation) - 실무자 - 장기 관점, 전사 관점, 판단 정보","전략(Strategy) - 경영층 - 장기적 관점, 전사 관점, 외부 정보 활용, 동적 정보/판단 정보","기획(Planning) - 부서장·기획부서 - 중단기 관점(3, 6개월), 주요 기능 관점, 의사결정 정보"],"a":1,"e":"운영(Operation) 범주는 실무자가 즉시 관점, 업무 수행 관점, 실제 거래 데이터, 거래정보를 다룬다.","s":"2장 3절 정보 요구 분석"},
  {"id":"C4-122","ch":4,"no":122,"q":"엔터티 도출 방법으로 제시되지 않은 것은?","c":["각종 서식·보고서로부터 도출","정보 전략 계획(ISP), 전사아키텍처 계획(EAP)으로부터 생성된 자료를 통하여 도출","데이터베이스 실행 계획으로부터 도출","현행 DBMS로부터 역공학(Reverse Engineering)으로 테이블·엔터티 추출"],"a":2,"e":"실행 계획은 SQL 성능 분석 도구이며 엔터티 도출 방법이 아니다.","s":"2장 3절 엔터티 도출"},
  {"id":"C4-123","ch":4,"no":123,"q":"엔터티 후보 식별 시 확인해야 할 사항으로 제시되지 않은 것은?","c":["우리가 관리하고자 하는 것인지를 따져 본다","가로와 세로를 가진 면적(집합)인지를 확인한다","해당 후보의 예상 데이터 건수가 1만 건 이상인지 확인한다","후보 엔터티의 개념 정립을 명확히 한다"],"a":2,"e":"데이터 건수 기준은 엔터티 후보 식별 기준이 아니다.","s":"2장 3절 엔터티 후보 식별"},
  {"id":"C4-124","ch":4,"no":124,"q":"엔터티 후보 선정 시 유의 사항으로 옳지 않은 것은?","c":["동의어처럼 보이더라도 함부로 버리지 않는다","프로세스에 너무 연연해하지 않는다","예외 경우를 최대한 상세히 파악하여 모두 반영한다","엔터티 가능성이 있다고 예상되면 일단 검토 대상에 올린다"],"a":2,"e":"예외 경우에 너무 집착하지 말아야 하며, 너무 깊게 들어가지 않아야 한다.","s":"2장 3절 엔터티 후보 선정 시 유의 사항"},
  {"id":"C4-125","ch":4,"no":125,"q":"수집된 엔터티의 '데이터 영역별 분류'에서 '장소' 모델 대상의 예시로 가장 적절한 것은?","c":["사원, 가입자, 회원, 고객","부품, 원재료, 연료, 저장품","계약, 수주, 주문, 발주, 재해","창고, 생산라인, 행정구역, 하천, 선거구"],"a":3,"e":"사람/물건/사건/장소로 분류하며, 장소에는 창고, 생산라인, 행정구역, 하천, 선거구 등이 해당한다.","s":"2장 3절 수집된 엔터티 분류"},
  {"id":"C4-126","ch":4,"no":126,"q":"엔터티 검증 기준으로 가장 적절하지 않은 것은?","c":["인스턴스가 포함할 내부 연관성 있는 속성에 의해 결정된 단일 개념을 대표해야 한다","추상화 수준이 높을수록 좋으므로 Party와 같은 통합 엔터티를 우선 적용한다","조직의 업무를 수행하는 데 필요한 의미 있는 정보를 나타내야 한다","특정 사례가 아닌 유사한 사물들을 대표하는 집합체여야 한다"],"a":1,"e":"추상화 수준이 높은 모델은 유연하지만 업무 이해가 어렵고 데이터 관리·무결성 보장이 어려우므로 가급적 지양한다.","s":"2장 3절 엔터티 검증"},
  {"id":"C4-127","ch":4,"no":127,"q":"추상화 수준이 높은 데이터 모델의 단점으로 제시되지 않은 것은?","c":["데이터 중복이 급격히 증가한다","유연성이 있지만 업무를 이해하기 어렵다","데이터 관리가 쉽지 않다","데이터 무결성 보장이 어렵다"],"a":0,"e":"추상화 수준이 높은 모델의 단점은 업무 이해 곤란, 데이터 관리 곤란, 무결성 보장 곤란이다.","s":"2장 3절 엔터티 검증"},
  {"id":"C4-128","ch":4,"no":128,"q":"엔터티 명명 시 지키지 말아야 할 규칙으로 제시되지 않은 것은?","c":["데이터 관리자의 승인을 받지 않은 약어 또는 두문자어(예: 규손금, 납방)","테이블, 파일, 메뉴, 보고서, 입력화면 같은 정보시스템 구성요소","두 가지 이상의 개념을 동시에 사용하는 표현","현업에서 사용하는 업무 용어"],"a":3,"e":"현업에서 사용하는 업무 용어는 오히려 사용해야 할 명명 규칙이다.","s":"2장 3절 엔터티명"},
  {"id":"C4-129","ch":4,"no":129,"q":"엔터티 설명 기술 시 포함해야 할 내용으로 가장 적절하지 않은 것은?","c":["엔터티의 범위(scope)와 인스턴스가 다른 인스턴스와 어떻게 구별되는지","엔터티가 저장될 테이블스페이스와 인덱스 구성","엔터티 그 자체가 무엇(what)인지","업무에서 왜(why) 중요한가"],"a":1,"e":"테이블스페이스·인덱스 구성은 물리 설계 영역이며 엔터티 설명 항목이 아니다.","s":"2장 3절 엔터티 설명"},
  {"id":"C4-130","ch":4,"no":130,"q":"엔터티 정의 사항 중 '현재 발생 건수'와 '발생 건수 변화'를 파악하는 목적으로 가장 적절한 것은?","c":["관계의 기수성을 결정하기 위해서","설계 및 구축 단계(DB 설계자·운영자 지원, 데이터 이행 시 저장공간 사용계획 수립)를 위해서","정규화 수준을 결정하기 위해서","서브타입을 도출하기 위해서"],"a":1,"e":"현재 발생 건수와 변화율은 설계·구축 단계의 DB 설계자·운영자 지원 및 저장공간 계획 수립을 위해 파악한다.","s":"2장 3절 엔터티 정의 사항"},
  {"id":"C4-131","ch":4,"no":131,"q":"엔터티 정의 사항의 '권한'에 대한 설명으로 옳은 것은?","c":["엔터티를 생성/수정/삭제하는 메타 데이터 권한과 엔터티의 데이터를 생성/수정/삭제하는 권한을 정의한다","데이터베이스 사용자 계정을 생성하는 권한만 정의한다","네트워크 접근 권한을 정의한다","백업·복구 수행 권한을 정의한다"],"a":0,"e":"권한은 메타 데이터 권한(엔터티 생성/수정/삭제)과 데이터 권한(데이터 생성/수정/삭제)으로 구분하여 정의한다.","s":"2장 3절 엔터티 정의 사항"},
  {"id":"C4-132","ch":4,"no":132,"q":"'집합의 동질성'에 대한 설명으로 가장 적절한 것은?","c":["동일한 성질을 어디까지로 한정할 것인가의 문제로, 사원 집합에 정직원·협력업체 직원·아르바이트를 포함할지 결정하는 것","개체 집합과 행위 집합이 충돌하지 않아야 한다는 것","엔터티가 다른 엔터티와 확연히 구분되는 독립성을 가져야 한다는 것","엔터티 명칭이 함축적 의미를 담아야 한다는 것"],"a":0,"e":"집합의 동질성은 동일한 성질을 어디까지로 한정할 것인가의 문제이다. 2번은 집합의 순수성이다.","s":"2장 3절 집합의 동질성"},
  {"id":"C4-133","ch":4,"no":133,"q":"'집합의 순수성'에 대한 설명으로 가장 적절한 것은?","c":["서브타입이 상호 배타적이어야 한다는 것이다","엔터티 명칭이 유일해야 한다는 것이다","개체집합이 되든지 아니면 활동을 위한 행위 집합이어야 하며 충돌이 있어서는 안 된다","동일한 성질을 어디까지 한정할지 결정하는 것이다"],"a":2,"e":"집합의 순수성은 개체 집합(고객, 상품)이거나 행위 집합(입금, 계약)이어야 하며 충돌(납입자, 입금자)이 있어서는 안 된다는 것이다.","s":"2장 3절 집합 순수성"},
  {"id":"C4-134","ch":4,"no":134,"q":"집합 순수성의 예외 사항으로 제시되지 않은 것은?","c":["일부 집합 정의(금융기관)","배타적 관계(배송처 - 고객, 공사현장, 물류센터)","정규화 위반 속성의 분리","릴레이션십의 엔터티화(피보험자)"],"a":2,"e":"집합 순수성의 예외 사항은 릴레이션십의 엔터티화, 일부 집합 정의, 배타적 관계이다.","s":"2장 3절 집합 순수성"},
  {"id":"C4-135","ch":4,"no":135,"q":"'납입자'와 같은 명칭이 집합 순수성을 해치는 이유로 가장 적절한 것은?","c":["동음이의어이기 때문","'납입'이라는 행위와 '자(者)'라는 개체가 혼합되어 있으며, 이는 고객 엔터티와 연관된 관계속성으로 보는 것이 타당하기 때문","명칭이 너무 길기 때문","한자어를 사용했기 때문"],"a":1,"e":"'납입 + 자'는 행위와 개체가 충돌한 형태이며, 고객 엔터티와 연관된 관계속성으로 보아야 한다.","s":"2장 3절 집합 순수성"},
  {"id":"C4-136","ch":4,"no":136,"q":"코드성 키 엔터티 모델링 시 검토해야 할 사항으로 제시되지 않은 것은?","c":["이 엔터티가 여러 엔터티에 관계를 가질 것인가","이 엔터티가 자신만의 다양한 속성을 가질 것인가","이 엔터티의 코드값이 10개를 초과하는가","이 엔터티가 자식 엔터티를 가지는가"],"a":2,"e":"코드값 개수는 판단 기준으로 제시되지 않았다.","s":"2장 3절 코드성 키 엔터티 모델링"},
  {"id":"C4-137","ch":4,"no":137,"q":"엔터티 일반화(서브타입) 특성에 대한 설명으로 옳지 않은 것은?","c":["서브타입은 자신의 속성이나 독립적인 관계를 가진다","자신의 속성이나 관계를 가지지 않는 서브타입은 존재할 수 없다","슈퍼타입은 두 개 이상의 독립적인 서브타입으로 구성된다","슈퍼타입은 각 서브타입들의 공통적인 속성과 관계를 가진다"],"a":1,"e":"자신의 속성이나 관계를 가지지 않는 서브타입도 존재할 수 있으며, 이 경우 일반적인 속성으로 처리한다.","s":"2장 3절 엔터티 일반화"},
  {"id":"C4-138","ch":4,"no":138,"q":"CASE*Method 방법론의 일반화 특징으로 옳지 않은 것은?","c":["슈퍼타입의 인스턴스는 서브타입 중 단 하나와 반드시 연결되어야 한다","서브타입은 서로 중첩되지 않아야 하며 그 전체집합은 슈퍼타입과 1:1이다","전체집합에 확신이 없다면 서브타입을 정의하지 않는다","슈퍼타입과 서브타입은 부모:자식 관계가 아니다"],"a":2,"e":"전체집합에 확신이 없다면 '기타' 구분을 생성한다.","s":"2장 3절 엔터티 일반화"},
  {"id":"C4-139","ch":4,"no":139,"q":"배타적(Exclusive) 일반화와 포함적(Inclusive) 일반화에 대한 설명으로 옳은 것은?","c":["배타적 표기법은 IE 표기법에서만 사용 가능하다","포함적 표기법은 슈퍼타입 인스턴스 하나가 서브타입 인스턴스 여러 개로 될 수 있으며 CASE*Method 표기법으로는 표현이 불가능하다","배타적 표기법은 슈퍼타입 인스턴스 하나가 여러 서브타입에 속할 수 있다","포함적 표기법은 서브타입의 교집합이 공집합이어야 한다"],"a":1,"e":"포함적 일반화는 슈퍼타입 인스턴스 하나가 여러 서브타입 인스턴스가 될 수 있으며 CASE*Method로는 표현이 불가능하다(DA# 툴에서는 지원).","s":"2장 3절 배타적/포함적 일반화"},
  {"id":"C4-140","ch":4,"no":140,"q":"서브타입 지정 시 고려 사항으로 옳지 않은 것은?","c":["개별 속성이나 개별 관계를 가지는 경우 또는 가독성 증진을 위해 표현","서브타입은 반드시 3개 이상으로 구성되어야 한다","교집합 허용 불가","서브타입의 합이 전체 집합"],"a":1,"e":"서브타입 개수에 대한 제한은 없으며, 슈퍼타입은 두 개 이상의 독립적인 서브타입으로 구성된다.","s":"2장 3절 서브타입"},
  {"id":"C4-141","ch":4,"no":141,"q":"서브타입 도출 근거로 제시되지 않은 것은?","c":["다수의 선택적 속성이 존재하여 서브타입 도출에 의해 필수 속성이 되는 경우","선택적 관계가 존재하여 서브타입으로 분할함으로써 관계가 필수적으로 변하는 경우","소수의 선택적 속성이 존재하는 경우","분류 속성에 따라 엔터티의 정보가 차별화되는 경우"],"a":2,"e":"서브타입 도출 근거는 분류 속성, 다수의 선택적 속성, 선택적 관계이며 소수의 선택적 속성은 해당하지 않는다.","s":"2장 3절 서브타입 도출"},
  {"id":"C4-142","ch":4,"no":142,"q":"서브타입 도출 절차의 순서로 가장 적절한 것은?","c":["서브타입 파악 → 속성 할당 → 분류 속성 확인 → 관계 정의","분류 속성 확인 → 분류 속성 값에 의해 분류되는 서브타입 파악 → 분류 속성에 따라 필수/선택적 분할 정의 → 서브타입별 속성 할당 → 슈퍼타입의 관계를 해당 서브타입에 정의","서브타입별 속성 할당 → 분류 속성 확인 → 서브타입 파악 → 관계 정의","슈퍼타입 관계 정의 → 서브타입 파악 → 분류 속성 확인 → 속성 할당"],"a":1,"e":"분류 속성 확인 → 서브타입 파악 → 필수/선택적 분할 정의 → 서브타입별 속성 할당 → 슈퍼타입 관계 정의 순이다.","s":"2장 3절 서브타입 도출"},
  {"id":"C4-143","ch":4,"no":143,"q":"서브타입 활용의 효과로 제시되지 않은 것은?","c":["속성의 선택성과 관계의 선택성을 제거할 수 있다","데이터베이스 저장 공간이 항상 감소한다","데이터 모델에 업무 규칙을 명확히 표현하여 업무를 정확히 이해할 수 있다","엔터티 정의를 구체화하여 데이터 모델에 대한 가독성이 향상된다"],"a":1,"e":"저장 공간 감소는 서브타입 활용의 효과로 제시되지 않았다. 서브타입 표현은 업무 규칙의 명확성과 표현의 복잡성 간 트레이드오프 관계이다.","s":"2장 3절 서브타입의 활용"},
  {"id":"C4-144","ch":4,"no":144,"q":"엔터티 통합과 분할에 대한 설명으로 가장 적절하지 않은 것은?","c":["나쁜 형태의 통합은 본질의 희석을 가져와 집합의 모호성을 증대시킨다","하위 엔터티일수록 통합의 효과가 높다","통합과 분할에 따라 개발 생산성, 난이도, 수행속도, 유연성, 유지보수 비용에 영향을 준다","좋은 형태의 통합은 변화에 대한 유연성을 증가시킨다"],"a":1,"e":"상위 엔터티일수록 통합의 효과가 높으며, 상위 엔터티가 분할되어 있으면 부모가 누구인지 찾기가 모호해진다.","s":"2장 3절 엔터티 통합과 분할"},
  {"id":"C4-145","ch":4,"no":145,"q":"'유연성 향상을 위한 통합'에 대한 설명으로 가장 적절한 것은?","c":["집합을 확장할수록 업무 이해도가 높아진다","집합의 확장은 성능을 항상 향상시킨다","집합의 확장은 유연성과 단순성을 증가시키지만 지나친 확장은 집합의 의미를 희석시킨다","집합의 확장은 항상 데이터 무결성을 향상시킨다"],"a":2,"e":"집합의 확장은 유연성과 단순성을 증가시키지만 지나친 확장은 집합의 의미를 희석시킨다.","s":"2장 3절 엔터티 통합과 분할"},
  {"id":"C4-146","ch":4,"no":146,"q":"일반화(Generalization)와 상세화(Specialization)의 장단점 비교로 옳지 않은 것은?","c":["일반화는 공통적이지 않은 속성이 많은 경우 효과가 반감된다","상세화는 업무에 대한 명확한 파악이 가능하고 장애·에러에 대한 파급효과가 작다","상세화는 동일한 로직을 하나의 프로그램으로 통합 관리할 수 있어 효율적이다","일반화는 데이터가 통합되어 조회가 간편하고 한 개의 프로그램으로 업무 처리가 가능하다"],"a":2,"e":"상세화는 동일한 로직도 별도의 프로그램으로 개발해야 하므로 관리가 비효율적이다.","s":"2장 3절 일반화 장단점"},
  {"id":"C4-147","ch":4,"no":147,"q":"일반화(통합)의 단점으로 제시되지 않은 것은?","c":["모든 업무를 이해하는 인원만이 데이터 관리를 수행할 수 있다","특정 업무에만 관련된 데이터 변경이 있을 경우 타 업무에 영향을 준다","엔터티(테이블)의 수효가 늘어나 관리의 어려움이 발생한다","여러 업무의 데이터가 서로 섞여 있어 내용을 정확하게 파악하기 힘들다"],"a":2,"e":"엔터티 수효 증가로 인한 관리 어려움은 상세화(분할)의 단점이다.","s":"2장 3절 일반화 장단점"},
  {"id":"C4-148","ch":4,"no":148,"q":"엔터티의 정의 요건으로 제시되지 않은 것은?","c":["관리하고자 하는 것인가","가로와 세로의 면적(집합)인지 확인","대상 개체 간의 동질성이 있는지, 다른 개체와 확연히 구분되는 독립성을 가지는지","물리적으로 하나의 테이블로 변환 가능한지"],"a":3,"e":"물리 테이블 변환 가능 여부는 물리 모델링 단계의 고려사항이며 엔터티 정의 요건이 아니다.","s":"2장 3절 엔터티"},
  {"id":"C4-149","ch":4,"no":149,"q":"'개념 데이터 모델링 순서'로 가장 적절한 것은?","c":["후보 엔터티 선정 → 주제영역 도출 → 핵심 엔터티 관계 설정 → 엔터티 분류 → 핵심 엔터티 정의","핵심 엔터티 정의 → 주제영역 도출 → 후보 엔터티 선정 → 관계 설정 → 엔터티 분류","주제영역 도출 → 핵심 엔터티 정의 → 후보 엔터티 선정 → 엔터티 분류 → 관계 설정","주제영역 도출 → 후보 엔터티 선정 → 수집된 엔터티 분류 → 핵심 엔터티 정의 → 핵심 엔터티 관계 설정"],"a":3,"e":"개념 데이터 모델링은 주제영역 도출 → 후보 엔터티 선정 → 수집된 엔터티 분류 → 핵심 엔터티 정의 → 핵심 엔터티 관계 설정 순으로 진행한다.","s":"2장 1절 개념 데이터 모델링 순서"},
  {"id":"C4-150","ch":4,"no":150,"q":"'후보 엔터티 선정' 단계의 성격에 대한 설명으로 가장 적절한 것은?","c":["엔터티 확정 단계가 아니고 후보의 자격 여부만 판별하며, 실제 엔터티는 별도의 단계를 거쳐 확정한다","후보 엔터티 선정 단계에서 엔터티가 최종 확정된다","후보 엔터티는 반드시 모두 엔터티로 확정된다","후보 엔터티는 물리 테이블과 1:1로 대응된다"],"a":0,"e":"후보 엔터티 선정은 후보의 자격 여부만 판별하는 단계이며, 실제 엔터티는 별도의 확정 단계를 거친다.","s":"2장 3절 후보 엔터티 선정 개념"},
  {"id":"C4-151","ch":4,"no":151,"q":"엔터티 후보 수집처로 제시되지 않은 것은?","c":["데이터베이스 성능 통계","기존 시스템 도큐먼트, 현업 장표·보고서","현업 인터뷰, 관련 전문 서적","데이터 흐름도(DFD), 타 시스템 자료, 현장조사"],"a":0,"e":"엔터티 후보 수집처는 기존 시스템 문서, 장표·보고서, 인터뷰, 전문 서적, DFD, 타 시스템 자료, 현장조사이다.","s":"2장 3절 엔터티 후보 수집"},
  {"id":"C4-152","ch":4,"no":152,"q":"수집된 엔터티 분류(데이터 영역별 분류)의 활용 목적으로 제시되지 않은 것은?","c":["통합과 분할의 기초 자료로 활용","엔터티 골격의 명확화","주제영역 확정","분류 자체는 주제영역과 무관하다는 점 인식"],"a":2,"e":"데이터 영역별 분류는 통합·분할의 기초 자료 활용과 엔터티 골격 명확화에 사용되며 주제영역과는 무관하다.","s":"2장 3절 수집된 엔터티 분류"},
  {"id":"C4-153","ch":4,"no":153,"q":"'의미상 주어(본질 식별자) 정의'의 의의로 가장 적절한 것은?","c":["엔터티의 물리적 저장 구조를 결정하기 위함","인덱스를 설계하기 위함","반정규화 대상을 선정하기 위함","집합의 의미가 모호한 상태에서는 객관적인 판단 진행이 불가능하므로 집합의 의미를 명확히 하기 위함"],"a":3,"e":"본질 식별자 정의는 집합의 의미를 명확히 하기 위한 것으로, 모호한 상태에서는 객관적 판단이 불가능하다.","s":"2장 3절 의미상 주어 정의"},
  {"id":"C4-154","ch":4,"no":154,"q":"관계(Relationship)의 관점에 대한 설명으로 옳지 않은 것은?","c":["두 엔터티 간에는 반드시 하나의 관계만 존재할 수 있다","항상 두 엔터티 간에 존재하며 항상 두 개의 관점을 가지고 있다","데이터의 양방향 업무 규칙(Business Rule)을 표현한다","외래키로 구현되어 참조 무결성으로 데이터의 정합성을 유지한다"],"a":0,"e":"두 엔터티 간에는 하나 이상의 관계가 존재할 수 있다(예: 보험계약-고객 관계).","s":"2장 4절 관계 이해"},
  {"id":"C4-155","ch":4,"no":155,"q":"관계 선택 사양(Optionality)의 '일반적인 형태'로 제시된 것은?","c":["양쪽 모두 옵셔널","1측 엔터티는 옵셔널, M측 엔터티는 필수","1측 엔터티는 필수, M측 엔터티는 옵셔널","양쪽 모두 필수"],"a":1,"e":"가장 많이 나타나는 형태는 1측 엔터티가 옵셔널, M측 엔터티가 필수인 형태이나, 이것이 꼭 바람직한 형태만은 아니다.","s":"2장 4절 관계 표현"},
  {"id":"C4-156","ch":4,"no":156,"q":"관계 선택 사양의 '바람직한 형태'에 대한 설명으로 가장 적절한 것은?","c":["부모 엔터티를 항상 선택으로 정의한다","선택성은 성능에만 영향을 주므로 논리 모델에서는 고려하지 않는다","가능한 직선(필수) 관계를 가지도록 노력하며 특히 자식 엔터티에 대해 그러하다","가능한 점선(선택) 관계를 많이 사용한다"],"a":2,"e":"가능한 직선 관계를 가지도록 노력해야 하며, 부모에 개체가 없는 자식 개체가 많이 발생하면 정보 정합성에 문제가 발생한다.","s":"2장 4절 관계 표현"},
  {"id":"C4-157","ch":4,"no":157,"q":"관계명(Relationship Name) 부여 원칙으로 옳지 않은 것은?","c":["다른 관계명과의 유일성을 반드시 확보해야 한다","능동/수동형의 사용은 가급적 배제한다","두 개의 관계 멤버십에 각각 부여하며 각자 상대방 입장에서의 관계명을 기술한다","현업에서 사용하는 간결한 동사형으로 현재 시제를 사용한다"],"a":0,"e":"관계명은 다른 관계명과의 유일성이 확보되지는 못한다.","s":"2장 4절 관계명"},
  {"id":"C4-158","ch":4,"no":158,"q":"관계명으로 부적절한 표현으로 제시된 것은?","c":["보유한다 / 발행한다","~ 관계가 있다 / ~ (관련이) 있다 / ~ 이다 / ~ 한다","소속된다 / 근무한다","주문한다 / 가르친다"],"a":1,"e":"업무적 의미가 없거나 애매모호한 용어(~관계가 있다, ~있다, ~이다, ~한다)는 배제해야 한다.","s":"2장 4절 관계명"},
  {"id":"C4-159","ch":4,"no":159,"q":"관계 유형에 대한 설명으로 옳지 않은 것은?","c":["사건 관계(Event Relationship) - '고객은 상품을 주문한다'","순환 관계(Recursive Relationship) - '고객은 주문을 한다'","존재 관계(Existence Relationship) - '부서에는 사원이 근무한다'","기능 관계(Function Relationship) - '교수는 학생을 가르친다'"],"a":1,"e":"순환 관계는 하나의 엔터티가 자기 자신과 맺는 관계이며 '고객은 주문을 한다'는 사건 관계에 해당한다.","s":"2장 4절 관계 도출"},
  {"id":"C4-160","ch":4,"no":160,"q":"M:M(다대다) 관계에 대한 설명으로 옳지 않은 것은?","c":["의외로 빈번하게 발생되나 데이터 모델링이 완료된 후에는 존재하지 않는다","1:M 관계로 분해했을 때 항상 1:M 관계로 분해된다","해소하지 않으면 카티션 프로덕트가 발생하고 정보의 왜곡이 생긴다","양쪽 모두가 점선인 것이 기본형이다"],"a":1,"e":"1:M 관계로 분해했을 때 항상 1:M으로 분해되는 것은 아니며, 상품과 주문 사이처럼 덜 분해된 M:M 관계가 나타날 수 있어 해소될 때까지 분해가 필요하다.","s":"2장 4절 관계 형태"},
  {"id":"C4-161","ch":4,"no":161,"q":"1:1 관계에 대한 설명으로 가장 적절하지 않은 것은?","c":["현실에서 매우 드물게 나타나는 형식이다","업무의 흐름에 따라 데이터가 설계된 형태에서 많이 나타난다","엔터티 수직 분할 시에 많이 나타난다","현실 세계에서 가장 흔한 형태이다"],"a":3,"e":"현실 세계에서 가장 흔한 형태는 M:1 관계이다.","s":"2장 4절 관계 형태"},
  {"id":"C4-162","ch":4,"no":162,"q":"M:1 관계에 대한 설명으로 가장 적절한 것은?","c":["내가 참조할 정보가 나에 대해서 하나만 존재해야만 하므로 참조할 때 내 집합에 변화가 생기지 않으며 내가 참조하는 엔터티는 반드시 1쪽이 될 수밖에 없다","양쪽 모두 점선인 것이 기본형이다","엔터티 수직 분할 시에 주로 나타난다","데이터 모델링 완료 후에는 존재할 수 없다"],"a":0,"e":"M:1 관계는 현실 세계에서 가장 흔한 형태로, 참조할 정보가 하나만 존재해야 하므로 참조 대상은 반드시 1쪽이 된다.","s":"2장 4절 관계 형태"},
  {"id":"C4-163","ch":4,"no":163,"q":"O:O(양쪽 선택) 1:1 관계에 대한 설명으로 가장 적절한 것은?","c":["M:M 관계로 변환해야 한다","자주 발생되지 않는 형태이며, 그대로 테이블로 설계하면 전체집합을 찾기 위해 항상 합집합을 만들어야 한다","현실 세계에서 가장 흔한 형태이다","반드시 하나의 테이블로 통합해야 한다"],"a":1,"e":"O:O 형태는 자주 발생하지 않으며 그대로 테이블로 설계하면 전체집합을 찾기 위해 항상 합집합을 만들어야 한다.","s":"2장 4절 관계 형태"},
  {"id":"C4-164","ch":4,"no":164,"q":"다중 관계 처리에서 '병렬식' 방식의 특징으로 옳은 것은?","c":["테이블이 될 때 여러 개의 칼럼으로 나열되며 하나의 로우에서 관리되므로 새로운 테이블 추가가 불필요하다","관계들이 로우 형태로 나타나며 인덱스 수가 감소하고 SQL이 단순해진다","새로운 관계의 추가나 관계 형태의 변경에 매우 유연하다","관계 내용별로 상세 정보 관리가 가능하다"],"a":0,"e":"2·3·4번은 직렬식의 특징이다. 병렬식은 칼럼 나열 방식으로 새로운 관계 추가·변경에 취약하다.","s":"2장 4절 다중 관계 처리"},
  {"id":"C4-165","ch":4,"no":165,"q":"다중 관계 처리에서 '직렬식' 방식의 단점으로 옳은 것은?","c":["관계들을 관리하는 새로운 엔터티가 추가로 필요하다","새로운 관계의 추가·변경에 매우 취약하다","관계 내용별로 상세 정보를 관리할 수 없다","자식 엔터티를 거느릴 수 없다"],"a":0,"e":"직렬식의 단점은 관계들을 관리하는 새로운 엔터티가 추가로 필요하다는 점이며, 2·3번은 병렬식의 단점이다.","s":"2장 4절 다중 관계 처리"},
  {"id":"C4-166","ch":4,"no":166,"q":"순환 관계(Recursive Relationship)에 대한 설명으로 옳지 않은 것은?","c":["순환 모델은 조직의 변경(추가/삭제)에 대응하기 어렵다","하나의 순환 엔터티는 각 엔터티의 모든 속성을 포함해야 한다","각 계층에 있는 속성은 동일하게 하는 것이 가장 좋다","순환 모델은 필수(직선) 관계로 취급될 수 없고 반드시 선택 사양이어야 한다"],"a":0,"e":"순환 모델의 특징은 조직의 변경(추가/삭제)에 쉽게 대응할 수 있다는 점이다.","s":"2장 4절 특수한 형태 관계"},
  {"id":"C4-167","ch":4,"no":167,"q":"계층 구조 모델과 계층 구조 순환 전개 모델의 비교로 옳지 않은 것은?","c":["순환 전개 모델은 계층 구조이면서 변동이 거의 없는 업무(예: 회계 계정과목)에 적용한다","계층 구조 모델은 사용이 쉽고 간편하며 수행 속도에 상대적으로 유리하다","계층 구조 모델은 계층 구조 변경 시 과거 데이터의 수정이 필요하다","순환 전개 모델은 계층 구조 변경에 매우 유연하며 과거 데이터의 수정이 없다"],"a":0,"e":"변동이 거의 없는 업무(회계 계정과목)에는 계층 구조 모델을, 변동이 발생하는 업무(조직)에는 순환 전개 모델을 적용한다.","s":"2장 4절 자기 참조 관계"},
  {"id":"C4-168","ch":4,"no":168,"q":"BOM(Bill of Materials) 관계에 대한 설명으로 가장 적절한 것은?","c":["1:M 순환 관계이며 자기 자신을 참조하는 외래키를 추가한다","배타적 관계의 한 형태이다","서브타입 관계의 한 형태이다","M:M 순환 관계이며 상세 모델링 과정에서 새로운 관계 엔터티를 추가하여 두 개의 1:M 관계로 구성한다"],"a":3,"e":"BOM 관계는 M:M 순환 관계이며, 상세 모델링 시 새로운 관계 엔터티를 추가하여 두 개의 1:M 관계로 구성한다.","s":"2장 4절 특수한 형태 관계"},
  {"id":"C4-169","ch":4,"no":169,"q":"배타적(Arc) 관계의 특성으로 옳지 않은 것은?","c":["아크 내에 있는 릴레이션십은 항상 필수이거나 선택사양이어야 한다","하나의 아크가 여러 엔터티를 가질 수 있다","어떤 엔터티는 다수의 아크를 가질 수 있으나 지정된 릴레이션십은 단 하나의 아크에만 사용되어야 한다","아크 내에 있는 릴레이션십은 보통 동일하다(기수성)"],"a":1,"e":"아크는 반드시 하나의 엔터티에만 속해야 하며, 하나의 아크가 여러 엔터티를 가질 수 없다.","s":"2장 4절 배타적 관계"},
  {"id":"C4-170","ch":4,"no":170,"q":"배타적 관계에서 두 개의 관계가 모두 선택(Optional)이고 Arc 관계일 때, 엔터티 인스턴스당 유효한 관계 수의 최소값과 최대값으로 옳은 것은?","c":["최소 n, 최대 n","최소 0, 최대 1","최소 1, 최대 1","최소 0, 최대 n"],"a":1,"e":"두 관계가 모두 선택이면서 Arc 관계이면 최소 0, 최대 1이다. 두 관계가 필수이면서 Arc이면 최소 1, 최대 1이다.","s":"2장 4절 배타적 관계"},
  {"id":"C4-171","ch":4,"no":171,"q":"배타적 관계를 표현할 수 있는 표기법에 대한 설명으로 옳은 것은?","c":["두 표기법 모두 표현 가능하다","두 표기법 모두 표현 불가능하다","CASE*Method 표기법으로는 표현 가능하나 ER-Win의 IDEF1X 표기법으로는 표현이 불가능하다","IE 표기법에서만 표현 가능하다"],"a":2,"e":"배타적 관계는 CASE*Method 표기법으로 표현 가능하나 ER-Win의 ID 표기법으로는 표현이 불가능하다.","s":"2장 4절 배타적 관계"},
  {"id":"C4-172","ch":4,"no":172,"q":"관계 정의 사항 중 '외래 키' 검토 항목으로 옳은 것은?","c":["외래 키가 부모 엔터티의 주 키와 일치하는가, 외래 키 항목이 주 키와 주 키가 아닌 속성에 펼쳐져 있는가","관계명이 동사형으로 부여되었는가","기수성과 선택성이 업무 규칙에 근거하였는가","관계가 왜 존재해야 하는가를 기술하고 있는가"],"a":0,"e":"외래 키 검토 항목은 부모 엔터티 주 키와의 일치 여부 및 주 키/비주 키 속성에 펼쳐져 있는지 여부이다.","s":"2장 4절 관계 정의 사항"},
  {"id":"C4-173","ch":4,"no":173,"q":"속성(Attribute)의 개념에 대한 설명으로 가장 적절하지 않은 것은?","c":["속성의 어원적 의미는 가공되지 않은 것, 원천을 의미한다","속성들 간은 서로 종속적이어야 한다","엔터티에 속하는 모든 인스턴스들이 공통으로 가지는 특성이다","데이터베이스 내에 저장되는 최소 단위의 정보이다"],"a":1,"e":"속성들 간은 서로 독립적이어야 하며, 이는 제3정규형과 관련된다.","s":"2장 5절 속성 개념"},
  {"id":"C4-174","ch":4,"no":174,"q":"속성 후보 선정 원칙으로 가장 적절한 것은?","c":["원시 속성으로 보이는 후보는 버리지 않으며, 소그룹별로 후보군(Pool)을 만들고 가장 근접한 엔터티에 할당한다","추출(Derived) 속성을 우선적으로 선정한다","모든 속성을 반드시 확정된 엔터티에만 할당한다","속성 후보는 엔터티 확정 이후에만 수집한다"],"a":0,"e":"다른 속성으로 재현할 수 없는 원시 속성 후보는 버리지 않으며, 모든 엔터티가 정의된 상태가 아니므로 소그룹별 후보군을 만들어 근접 엔터티에 할당한다.","s":"2장 5절 속성 후보 도출"},
  {"id":"C4-175","ch":4,"no":175,"q":"속성명 부여 원칙으로 옳지 않은 것은?","c":["실체명(엔터티명)은 속성명으로 사용하지 말아야 한다","속성명은 여러 실체에 중복 사용되도록 일반화하는 것이 바람직하다","속성의 의미를 명확히 표현하는 함축성 있는 명사 혹은 명사구를 사용한다","해당 업무에서 일반적으로 사용하는 용어를 사용한다"],"a":1,"e":"필요 시 표준 약어를 제정하여 속성명을 생성하고 그 속성명을 단 하나의 실체에만 속하도록 하는 것이 바람직하다.","s":"2장 5절 속성의 기본 구성 요소"},
  {"id":"C4-176","ch":4,"no":176,"q":"속성명 부여 형태 '엔터티명 + 수식어 + 도메인명'과 관련하여 옳은 것은?","c":["모든 속성은 반드시 엔터티명을 접두어로 포함해야 한다","'최초입력일자'처럼 도메인이 같은 속성도 반드시 엔터티명을 포함해야 한다","속성명은 복수형으로 사용한다","'고객상태코드', '사원상태코드'처럼 엔터티별 도메인이 다르면 엔터티명을 포함하여 구분한다"],"a":3,"e":"도메인이 서로 다른 경우 엔터티명을 포함해 구분하고, '최초입력일자'처럼 도메인이 같으면 엔터티명을 함께 표기할 필요가 없다. 속성명은 단수형을 사용한다.","s":"2장 5절 속성명"},
  {"id":"C4-177","ch":4,"no":177,"q":"속성 정의 시 유의 사항 중 '작위적인 전용 금지'에서 '전용'의 의미로 가장 적절한 것은?","c":["속성을 추출 속성으로 변경하는 것","속성명을 영문으로 변환하는 것","A 용도로 만들어 놓고 B 용도로 사용하는 것","속성을 다른 엔터티로 이동시키는 것"],"a":2,"e":"전용이란 A 용도로 만들어 놓고 B 용도로 사용하는 것이다.","s":"2장 5절 속성 정의 시 유의 사항"},
  {"id":"C4-178","ch":4,"no":178,"q":"전용이 발생하는 사례로 제시되지 않은 것은?","c":["모델러가 속성의 의미를 매우 추상적·모호하게 정의하여 개발자들이 각기 다르게 이해하는 경우","개발 막바지 또는 운용 중인 시스템에서 새로운 요구사항으로 새로운 속성 추가가 필요할 때","ERP 패키지에서 미리 전용의 용도로 속성을 정의해 두는 경우","표준 단어 사전을 사전에 제정한 경우"],"a":3,"e":"표준 단어 사전을 사전에 제정하는 것은 전용을 방지하기 위한 활동이다.","s":"2장 5절 속성 정의 시 유의 사항"},
  {"id":"C4-179","ch":4,"no":179,"q":"속성 정의 사항 중 '선택성 조건'에 대한 설명으로 가장 적절한 것은?","c":["속성의 데이터 타입과 길이를 의미한다","속성의 기본값을 의미한다","속성의 선택성이 다른 속성 값에 의해 영향을 받는 것으로 필요조건·금지조건·무관계조건으로 구분된다","속성이 반드시 값을 가져야 하는지 여부만을 의미한다"],"a":2,"e":"선택성 조건은 다른 속성 값에 의해 선택성이 영향을 받는 경우이며, 예로 고객등급코드가 '일반'이면 카드신용도가 필수, 'VIP'이면 금지가 된다.","s":"2장 5절 선택성 및 선택성 조건"},
  {"id":"C4-180","ch":4,"no":180,"q":"속성 유형에 대한 설명으로 옳지 않은 것은?","c":["기본(Basic) 속성 - 속성 값이 해당 인스턴스에 원래 존재하여 다른 속성 값으로부터 유도될 수 없는 속성","유도(Derived) 속성 - 속성 값이 항상 다른 속성 값으로부터 유도되거나 계산되는 속성","설계(Designed) 속성 - 업무 제약사항을 반영하거나 시스템 운영을 단순화하기 위하여 생성하는 속성","유도 속성 - 논리 데이터 모델에서는 표기하지 않고 물리 모델에서만 표기한다"],"a":3,"e":"유도 속성과 유도 알고리즘은 논리 데이터 모델 단계부터 표기해야 한다.","s":"2장 5절 속성 유형"},
  {"id":"C4-181","ch":4,"no":181,"q":"속성 검증 시 '원자 값 단위까지 분할' 원칙에 대한 설명으로 가장 적절하지 않은 것은?","c":["원자 값이 아닌 속성은 접근경로(Access path)를 잃어버린다","일자, 시간, 성명, 주민번호, 우편번호 등은 일반적으로 분할하지 않는 것이 좋다","가능한 최소 단위까지 분할한 후에는 어떤 경우에도 다시 통합해서는 안 된다","계좌번호(16) = 지점코드(3) + 상품코드(2) + 계좌개설일자(8) + 일련번호(3)처럼 복합 의미를 가진 속성은 분해를 검토한다"],"a":2,"e":"가능한 최소 단위까지 분할한 후 관리 필요에 따라 통합하며, 분할·통합의 기준은 업무의 요구 사항에 따른다.","s":"2장 5절 속성 검증 및 확정"},
  {"id":"C4-182","ch":4,"no":182,"q":"원자 값 속성 사례 분석 중 '생년월일(DDMMYYYY)'에 대한 설명으로 가장 적절한 것은?","c":["날짜 타입으로만 정의해야 하며 분리는 불가능하다","특정 월일(DDMM) 캠페인처럼 부분이 의미를 가질 수 있으므로 연도(YYYY)와 월일(DDMM)을 분리할 수 있다","반드시 하나의 통합 속성으로만 관리해야 한다","반드시 연·월·일 3개 속성으로 분리해야 한다"],"a":1,"e":"매출일자는 통합했을 때만 의미를 갖지만, 생년월일은 특정 월일 캠페인 등에서 의미가 있어 연도와 월일로 분리할 수 있다.","s":"2장 5절 원자 값 속성 사례 분석"},
  {"id":"C4-183","ch":4,"no":183,"q":"'외부에서 만들어진 공인된 속성'(우편번호, 주민등록번호, 사업자등록번호 등)에 대한 처리로 가장 적절한 것은?","c":["반드시 구성 요소별로 분리하여 관리해야 한다","내부 코드 체계로 변환하여 관리해야 한다","암호화하여 하나의 문자열로 저장해야 한다","조직 외부에서 만들어졌으므로 외부에서 정해진 형태 그대로 사용하는 것이 바람직하다"],"a":3,"e":"외부에서 공인된 속성은 외부에서 정해진 형태 그대로 사용하는 것이 바람직하다(예: 우편번호 체계 변경 시 부분 사용은 문제 발생).","s":"2장 5절 원자 값 속성 사례 분석"},
  {"id":"C4-184","ch":4,"no":184,"q":"전화번호 유형 속성의 분리 여부에 대한 설명으로 가장 적절한 것은?","c":["속성의 분리 여부는 그 속성을 사용하는 조직의 업무에 따라 다르며, 일반적인 회사는 분리해서 사용하는 경우가 거의 없다","반드시 지역번호·국번호·개별번호로 분리해야 한다","반드시 하나의 속성으로 통합해야 한다","통신사와 일반회사 모두 동일하게 처리해야 한다"],"a":0,"e":"전화번호의 분리 여부는 업무에 따라 다르며, 통신사와 일반회사의 처리가 다를 수 있다.","s":"2장 5절 원자 값 속성 사례 분석"},
  {"id":"C4-185","ch":4,"no":185,"q":"단일 값(Single Value) 검증 사례로 옳지 않은 것은?","c":["차량번호는 고객이 하나 이상 가질 수 있으므로 고객차량의 속성이다","취미는 고객이 여러 개를 가질 수 있으므로 별도 처리가 필요하다","여러 값을 가지거나 반복되는 속성은 제3정규화 대상이 된다","계약일자는 고객이 여러 개를 가질 수 있으므로 고객의 속성이 아니라 가입계약의 속성이다"],"a":2,"e":"반복되는 속성은 새로운 엔터티로 분할해야 할 제1정규화 대상이다.","s":"2장 5절 속성 검증 및 확정"},
  {"id":"C4-186","ch":4,"no":186,"q":"추출(유도) 속성의 대표적 유형에 해당하지 않는 것은?","c":["기본 정보만 관리하는 형태(고객번호, 고객명)","현재 정보만 관리하는 형태(현주소, 현고객등급코드)","최초 정보를 보관하는 형태(최초가입일자, 모집사원번호)","집계 정보를 관리하는 형태(인원 수, 가족 수, 총직원 수)"],"a":0,"e":"고객번호·고객명은 기본(Basic) 속성이며 추출 속성 유형이 아니다.","s":"2장 5절 유도 속성인지 검증"},
  {"id":"C4-187","ch":4,"no":187,"q":"추출 속성 유형 중 '추출 관계만 관리하는 형태'에 대한 설명으로 가장 적절한 것은?","c":["하위 엔터티 정보의 집계(건수·횟수·차수)를 관리하는 경우","다른 속성의 일부 정보만 분리한 경우","자식 엔터티의 식별자를 전부 또는 일부만 옮겨둔 경우로 대부분 마지막 건의 식별자를 사용한다","자식 엔터티의 여러 정보 중 가장 대표적인 것 하나만 선정하여 사용하는 경우"],"a":2,"e":"추출 관계만 관리하는 형태는 자식 엔터티의 식별자를 전부 또는 일부 옮겨둔 경우로 대부분 마지막 건의 식별자를 사용한다.","s":"2장 5절 유도 속성인지 검증"},
  {"id":"C4-188","ch":4,"no":188,"q":"유도(Derived) 속성 규칙에 대한 설명으로 옳지 않은 것은?","c":["현재는 경영층이 관심을 보이는 속성으로 데이터 모델 내에 반드시 기술할 것을 권장한다","유도 속성은 사용자들의 데이터 요구 사항을 나타내며 물리적 구현에 대한 것을 내포하지 않는다","유도 속성은 향후 기본키(Primary Key)로서의 역할을 맡을 수 있다","초기 데이터 모델링 이론에서는 중복으로 인식하여 데이터 모델에 표현하지 않을 것을 권고하였다"],"a":2,"e":"유도(도출) 속성은 향후 과정으로써 결코 기본키로서의 역할을 맡아서는 안 된다.","s":"2장 5절 유도 속성 규칙"},
  {"id":"C4-189","ch":4,"no":189,"q":"계산(Calculated) 속성에 대한 설명으로 가장 적절한 것은?","c":["여러 엔터티의 값을 집계하여 산출한다","시스템 운영을 단순화하기 위해 생성한다","업무 제약사항을 반영하기 위해 생성한다","엔터티의 단일 사례에 대한 어떤 특성을 기술하며 일반적으로 관련 속성의 또 다른 단일 사례로부터 계산된다"],"a":3,"e":"계산 속성은 엔터티의 단일 사례에 대한 특성을 기술하며 관련 속성의 또 다른 단일 사례로부터 계산된다.","s":"2장 5절 유도 속성 규칙"},
  {"id":"C4-190","ch":4,"no":190,"q":"속성의 '소유 권한'에 대한 설명으로 가장 적절한 것은?","c":["데이터베이스 계정 권한만을 의미한다","속성의 도메인 정의 권한만을 의미한다","속성의 인덱스 생성 권한을 의미한다","속성 자체를 생성/삭제/수정할 수 있는 메타 데이터 승인 권한과 데이터(속성 값) 생성/사용 권한을 가지는 개인·기능·조직을 기록 관리한다"],"a":3,"e":"소유 권한은 데이터 거버넌스 차원에서 메타 데이터 승인 권한과 데이터 생성/사용 권한을 가지는 주체를 기록 관리하는 것이다.","s":"2장 5절 소유 권한"},
  {"id":"C4-191","ch":4,"no":191,"q":"식별자의 종류에 해당하지 않는 것은?","c":["인조 식별자(Artificial Identifier, Surrogate Key)","보조(대체) 식별자(Alternate Identifier)","참조 식별자(Reference Identifier)","본질 식별자(Natural Identifier)"],"a":2,"e":"식별자 종류는 본질 식별자, 인조 식별자, 후보 식별자, 대체(보조) 식별자, 실질 식별자이다.","s":"2장 6절 식별자 개념"},
  {"id":"C4-192","ch":4,"no":192,"q":"거래 처리 엔터티의 본질 식별자를 찾는 방법으로 가장 적절한 것은?","c":["데이터 건수가 가장 적은 속성을 선택한다","부모 엔터티가 누구인지(하나의 인스턴스를 유일하게 발생시키는 일련의 속성이 어떤 것인지)를 확인하는 방식으로 육하원칙을 이용한다","임의의 일련번호를 부여한다","가장 많이 사용되는 속성을 선택한다"],"a":1,"e":"거래 처리 엔터티의 본질 식별자는 부모 엔터티를 확인하는 방식으로 도출하며 육하원칙(누가·무엇을·언제·어디서)을 이용한다.","s":"2장 6절 식별자 종류"},
  {"id":"C4-193","ch":4,"no":193,"q":"본질 식별자의 육하원칙 중 '일반 속성'에 해당하는 것으로 묶인 것은?","c":["어떻게(행위의 결과), 왜(행위의 원인)","누가(행위의 주체), 무엇을(행위의 대상)","언제(행위의 발생 시간), 어디서(행위의 발생 장소)","누가, 언제"],"a":0,"e":"누가·무엇을·언제·어디서는 본질 식별자, 어떻게(행위의 결과)·왜(행위의 원인)는 일반 속성에 해당한다.","s":"2장 6절 본질 식별자"},
  {"id":"C4-194","ch":4,"no":194,"q":"'절대종속'과 '상대종속'에 대한 설명으로 옳은 것은?","c":["절대종속은 1촌 관계, 상대종속은 2촌 이상의 관계이다","두 개념은 동일하다","절대종속은 나를 태어나게 하는 엔터티와의 관계(상품-계좌, 카드-카드사용)이고, 상대종속은 나의 탄생과는 관계가 없으나 관계를 맺고 있는 것(각종 코드)이다","절대종속은 각종 코드와의 관계이고 상대종속은 부모 엔터티와의 관계이다"],"a":2,"e":"절대종속은 나를 태어나게 하는 엔터티와의 관계이고, 상대종속은 탄생과 무관하나 관계를 맺고 있는 것이다. 직접·간접종속은 1촌 여부로 구분한다.","s":"2장 6절 본질 식별자"},
  {"id":"C4-195","ch":4,"no":195,"q":"후보 식별자 도출 조건으로 옳지 않은 것은?","c":["후보 식별자의 데이터는 자주 변경되는 것이 유리하다","널(NULL)이 될 수 없다","각 인스턴스를 유일하게 식별할 수 있어야 한다","나머지 속성들을 직접 식별할 수 있어야 한다"],"a":0,"e":"후보 식별자의 데이터는 자주 변경되지 않는 것이어야 하며, 자주 변경되면 인덱스 트리 재구성 부담으로 성능이 저하된다.","s":"2장 6절 후보 식별자 도출"},
  {"id":"C4-196","ch":4,"no":196,"q":"후보 식별자로 속성 집합을 선택할 때 '개념적으로 유일해야 한다'는 조건의 예로 옳은 것은?","c":["(부서+성명)은 부서 내 동명이인이 가능하므로 부적절하고, (부서명+팀명)은 부서 내 같은 팀명이 없으므로 적절하다","(부서+성명)은 적절하고 (부서명+팀명)은 부적절하다","두 조합 모두 적절하다","두 조합 모두 부적절하다"],"a":0,"e":"현재 데이터가 유일하더라도 개념적으로 중복 가능하면 후보 식별자로 부적절하다.","s":"2장 6절 후보 식별자 도출"},
  {"id":"C4-197","ch":4,"no":197,"q":"보조(대체) 식별자에 대한 설명으로 가장 적절한 것은?","c":["원래의 식별자를 대신할 수 있는 또 다른 속성이나 관계로, 유일한 식별은 가능하나 대표성을 갖지 못한다","인위적으로 만든 속성으로 유일성을 보장한다","기준 정보 엔터티에서 인위적으로 생성한 식별자이다","부모로부터 상속받은 식별자이다"],"a":0,"e":"보조(대체) 식별자는 유일한 식별은 가능하나 대표성을 갖지 못하며, 예로 사원번호 대신 주민등록번호를 사용하는 경우가 있다.","s":"2장 6절 보조 식별자"},
  {"id":"C4-198","ch":4,"no":198,"q":"인조 식별자 지정 원칙으로 옳지 않은 것은?","c":["최대한 범용적인 값을 사용한다(사원번호, 상품코드, HS코드, 국가/통화코드 등)","유일한 값을 만들기 위한 인조 식별자를 사용한다","하나의 인조 식별자 속성으로 대체할 수 없는 형태를 주의한다","편의성·단순성 확보를 위해서는 인조 식별자를 사용해서는 안 된다"],"a":3,"e":"속성의 길이가 너무 길거나 기억하기 어려울 때 편의성·단순성 확보를 위해 인조 식별자를 사용할 수 있다.","s":"2장 6절 인조 식별자 지정"},
  {"id":"C4-199","ch":4,"no":199,"q":"이력을 대체하는 일련번호 인조식별자를 가진 엔터티가 자식을 갖게 될 때 발생할 수 있는 문제로 가장 적절한 것은?","c":["부모에 변경이력이 발생하면 자식에 변경이 없더라도 새로운 이력 일련번호를 상속하여 자식을 다시 만들어야 하는 상황이 발생할 수 있다","자식 엔터티의 인덱스가 무효화된다","자식 엔터티의 참조무결성이 자동 해제된다","자식 엔터티의 저장 공간이 감소한다"],"a":0,"e":"이력 일련번호 인조식별자가 상속되면 부모 이력 발생 시 자식을 다시 생성해야 하는 문제가 생겨 정보 활용에 혼란·왜곡이 발생할 수 있다.","s":"2장 6절 인조 식별자 지정"},
  {"id":"C4-200","ch":4,"no":200,"q":"'내부적으로만 사용하는 인조 식별자'에 대한 설명으로 가장 적절한 것은?","c":["현업 사용자에게는 알려주지 않고 시스템 내부적으로만 사용하는 형태로 시스템적인 필요성에 의해 도입한다","현업 사용자에게 반드시 공개해야 한다","외부 기관과의 데이터 교환에 사용한다","법정 식별자로 사용한다"],"a":0,"e":"내부적으로만 사용하는 인조 식별자는 현업 사용자에게 알려주지 않고 시스템 내부적 필요에 의해 사용한다(예: Oracle의 테이블 ID).","s":"2장 6절 인조 식별자 지정"},
  {"id":"C4-201","ch":4,"no":201,"q":"식별 관계(UID Bar)의 두 가지 의미로 옳게 묶인 것은?","c":["분류로서의 역할, 통합으로서의 역할","식별자로서의 역할, 정보로서의 역할","성능으로서의 역할, 보안으로서의 역할","제약으로서의 역할, 인덱스로서의 역할"],"a":1,"e":"식별 관계는 식별자로서의 역할과 정보로서의 역할(상대방 식별자 상속으로 정보 증가)을 갖는다.","s":"2장 6절 식별자 확정"},
  {"id":"C4-202","ch":4,"no":202,"q":"'식별자 상속과 단절의 원리'에 대한 설명으로 가장 적절한 것은?","c":["식별자 상속은 성능에만 영향을 준다","내 식별자에 부모의 식별자를 포함시키지 않는 순간 내 자손들에게는 더 이상 조상의 식별자를 상속시키지 못한다","식별자 상속은 무조건 많이 할수록 좋다","식별자 단절은 참조무결성을 위반한다"],"a":1,"e":"부모의 식별자를 내 식별자에 포함시키지 않으면 자손에게 조상의 식별자를 상속시키지 못하며, 적절한 상속·단절 전략은 처리의 단순화를 가져온다.","s":"2장 6절 식별자 확정"},
  {"id":"C4-203","ch":4,"no":203,"q":"식별자 확정 절차에서 '중요 거래 처리(메인) 엔터티'의 식별자 확정 전략으로 가장 적절한 것은?","c":["반드시 모든 부모의 식별자를 상속받아야 한다","식별자를 정의하지 않아도 된다","하위에 거느리는 엔터티 상황을 감안하여 식별자 속성의 개수를 적게 하며 경우에 따라 전체를 대신하는 인조 식별자를 생성한다","반드시 본질 식별자를 그대로 사용해야 한다"],"a":2,"e":"메인 엔터티는 상위 엔터티로서 자식을 많이 낳을 수 있으므로 식별자 속성 개수를 적게 하는 것이 좋으며 인조 식별자를 생성하기도 한다.","s":"2장 6절 식별자 확정 절차"},
  {"id":"C4-204","ch":4,"no":204,"q":"식별자 확정 절차에서 '기타 거래 처리(액션) 엔터티'에 대한 지침으로 가장 적절한 것은?","c":["인조 식별자를 적극 사용하는 것이 바람직하다","식별자를 부여하지 않는다","반드시 단일 속성 식별자를 사용한다","인조 속성을 많이 사용하지 않는 것이 바람직하며 본질 식별자를 지정하는 것이 좋다"],"a":3,"e":"액션 엔터티는 인조 식별자를 많이 사용하면 정보로서의 가치가 현저히 감소하므로 본질 식별자를 지정하는 것이 바람직하다.","s":"2장 6절 식별자 확정 절차"},
  {"id":"C4-205","ch":4,"no":205,"q":"정규화(Normalization)에 대한 설명으로 가장 적절하지 않은 것은?","c":["제1정규형에서 제3정규형까지만 정의되어 있다","엔터티에 데이터의 입력·수정·삭제 연산 수행 시 발생하는 이상(Anomaly) 현상을 제거하는 과정이다","정확성·일관성·단순성·비중복성·안정성을 만족시키는 최적의 데이터 구조를 만들어가는 과정이다","엔터티를 관련이 있는 속성들로만 구성하기 위해 엔터티를 분해하는 과정이다"],"a":0,"e":"정규화는 제1정규형(1NF)부터 제5정규형(5NF)과 BCNF까지로 구성된다.","s":"2장 7절 정규화 정의"},
  {"id":"C4-206","ch":4,"no":206,"q":"정규화의 장점으로 제시되지 않은 것은?","c":["중복값이 줄어들고 NULL 값이 줄어든다","복잡한 코드로 데이터 모델을 보완할 필요가 없다","새로운 요구 사항의 발견 과정을 돕고 업무 규칙의 정밀한 포착을 보증한다","조인 횟수가 감소하여 조회 성능이 향상된다"],"a":3,"e":"정규화는 엔터티를 분해하므로 조인이 증가할 수 있다. 정규화의 장점은 중복·NULL 감소, 코드 보완 불필요, 요구사항 발견, 업무 규칙 포착, 데이터 구조 안정성 최대화이다.","s":"2장 7절 정규화 장점"},
  {"id":"C4-207","ch":4,"no":207,"q":"이상(Anomaly) 현상에 대한 설명으로 옳지 않은 것은?","c":["수정 이상 - 일부 속성 값을 수정함으로써 원하지 않는 정보의 이상 현상이 발생하는 것","삭제 이상 - 일부 정보를 삭제함으로써 유지되어야 할 정보까지도 연쇄 삭제되는 현상","조회 이상 - 조회 시 인덱스를 사용하지 못하는 현상","입력 이상 - 별도의 사실이 발생하기 전까지 원하는 데이터를 입력할 수 없거나 불필요한 데이터도 함께 입력해야 하는 구조"],"a":2,"e":"이상 현상은 입력·수정·삭제 이상이며 조회 이상은 정규화 이론의 이상 현상이 아니다.","s":"2장 7절 정규화 과정"},
  {"id":"C4-208","ch":4,"no":208,"q":"제1정규형(1NF)의 정의에 해당하지 않는 것은?","c":["모든 속성은 반드시 하나의 값을 가져야 하며 반복 형태가 있어서는 안 된다","각 속성의 모든 값은 동일한 형식이어야 한다","각 속성들은 유일한 이름을 가져야 한다","식별자가 아닌 모든 속성은 식별자 전체 속성에 완전 종속되어야 한다"],"a":3,"e":"'식별자가 아닌 모든 속성은 식별자 전체 속성에 완전 종속되어야 한다'는 것은 제2정규형의 정의다. 제1정규형은 모든 속성이 반드시 하나의 값을 가지고 반복 형태가 없을 것, 각 속성의 모든 값이 동일한 형식일 것, 각 속성이 유일한 이름을 가질 것을 요구한다.","s":"2장 7절 제1정규형"},
  {"id":"C4-209","ch":4,"no":209,"q":"제1정규화 대상의 예로 가장 적절한 것은?","c":["자택전화번호, 직장전화번호, 휴대폰번호, 제3전화번호처럼 비슷한 유형의 속성이 반복되는 경우","고객명이 고객번호에 종속되는 경우","상품명이 복합 식별자의 일부인 상품코드에만 종속되는 경우","식별자가 종속자가 되는 경우"],"a":0,"e":"비슷한 유형의 속성이 반복되거나 값이 반복되면 제1정규화 대상이다. 2번은 3NF, 3번은 2NF, 4번은 BCNF 대상이다.","s":"2장 7절 제1정규형"},
  {"id":"C4-210","ch":4,"no":210,"q":"CJ. Date(1986)의 제2정규형 정의로 가장 적절한 것은?","c":["릴레이션 R이 제1정규형에 속하고 모든 Non-key 속성이 주 키에 완전 종속됨과 동치이다","릴레이션 R이 제2정규형에 속하고 모든 Non-key 속성이 주 키에 비이행적으로 종속됨과 동치이다","모든 기초를 이루는 정의역이 원자 값만을 담고 있다","식별자는 결정자이어야 한다"],"a":0,"e":"CJ. Date의 2NF 정의는 1NF에 속하고 모든 Non-key 속성이 주 키에 완전 종속되는 것이다. 2번은 3NF, 3번은 1NF, 4번은 BCNF이다.","s":"2장 7절 제2정규형"},
  {"id":"C4-211","ch":4,"no":211,"q":"제2정규화 위반 사례에 대한 조치로 가장 적절한 것은?","c":["식별자(주문번호+상품코드) 중 상품코드에만 종속되는 상품명을 상위 부모 엔터티(상품)로 분리하고 UID BAR를 상속받게 한다","고객명을 고객 엔터티로 분리하고 비식별 관계로 상속받게 한다","반복 속성을 별도의 1:M 엔터티로 분리한다","결정자가 아닌 식별자를 분리한다"],"a":0,"e":"2NF 위반 시 부분 종속되는 속성을 상위 부모 엔터티로 분리하며 UID BAR를 상속받는다. 2번은 3NF 조치이다.","s":"2장 7절 제2정규형"},
  {"id":"C4-212","ch":4,"no":212,"q":"제3정규형(3NF)에 대한 설명으로 가장 적절한 것은?","c":["다치 종속성을 제거해야 한다","제2정규형을 만족하고 식별자를 제외한 나머지 속성들 간의 종속이 존재하면 안 된다","모든 속성이 하나의 원자 값을 가져야 한다","식별자가 결정자이어야 한다"],"a":1,"e":"3NF는 2NF를 만족하고 식별자가 아닌 속성 간에 서로 종속될 수 없다(속성 간 종속성 배제).","s":"2장 7절 제3정규형"},
  {"id":"C4-213","ch":4,"no":213,"q":"제3정규형 위반 시 생성되는 관계의 형태로 옳은 것은?","c":["부모 엔터티가 생성되고 UID BAR를 통해 식별 관계로 상속받는다","자식 엔터티가 생성되고 M:M 관계가 된다","배타적 관계가 생성된다","부모 엔터티가 생성되고 그 부모 엔터티로부터 식별자가 아닌 비식별 관계로 상속받는다"],"a":3,"e":"3NF 위반 시 부모 엔터티가 생성되고 그로부터 식별자가 아닌 비식별 관계로 상속받는다.","s":"2장 7절 제3정규형"},
  {"id":"C4-214","ch":4,"no":214,"q":"BCNF(보이스-코드 정규형)에 대한 설명으로 가장 적절한 것은?","c":["다치 종속성을 제거한다","조인 종속성을 제거한다","부분 함수 종속성을 제거한다","식별자는 결정자이어야 하며 식별자가 종속자가 되어서는 안 된다"],"a":3,"e":"BCNF는 결정자 함수 종속성과 관련되며 식별자가 종속자가 되어서는 안 된다(분리 필요).","s":"2장 7절 정규화 과정"},
  {"id":"C4-215","ch":4,"no":215,"q":"정규형과 명칭·발표자의 연결이 옳지 않은 것은?","c":["3정규형 - 이행 함수 종속성 - E.F. Codd","BC정규형 - 결정자 함수 종속성 - R.F. Boyce, E.F. Codd","4정규형 - 조인 종속성 - Ronald Fagin","1정규형 - 완전 함수 종속성 - E.F. Codd"],"a":2,"e":"4정규형은 다중 값 종속성(1977), 5정규형이 조인 종속성(1979)이며 둘 다 Ronald Fagin이 발표하였다.","s":"2장 7절 정규화 정리"},
  {"id":"C4-216","ch":4,"no":216,"q":"함수적 종속성에 대한 설명으로 옳은 것은?","c":["사원번호 → 이름에서 결정자는 이름, 종속자는 사원번호이다","함수적 종속성은 물리 모델링 단계에서만 고려한다","함수적 종속성은 반정규화의 근거이다","사원번호 → 이름, 사원번호 → 연락처에서 결정자는 사원번호, 종속자는 이름·연락처이다"],"a":3,"e":"함수적 종속성에서 화살표의 왼쪽이 결정자, 오른쪽이 종속자이다.","s":"2장 7절 함수적 종속성"},
  {"id":"C4-217","ch":4,"no":217,"q":"M:M 관계 해소에 대한 설명으로 가장 적절하지 않은 것은?","c":["M:M 관계는 새로운 관계 엔터티를 추가하여 M:1 관계로 변경한다","M:M 관계는 최종적으로 완성된 데이터 모델에도 존재할 수 있다","M:M 관계는 논리 데이터 모델링 과정에서 많이 나타나며 데이터 모델이 아직 덜 완성된 모습이다","키 엔터티와 키 엔터티의 관계는 대부분 M:M 관계이므로 상세화 과정에서 액션 엔터티가 새롭게 도출된다"],"a":1,"e":"M:M 관계는 최종적으로 완성된 데이터 모델에는 존재할 수 없는 형태이다.","s":"2장 7절 M:M 관계 해소"},
  {"id":"C4-218","ch":4,"no":218,"q":"M:M 관계를 해소하지 않았을 때의 문제점으로 제시되지 않은 것은?","c":["모델은 정규화되지 못하고 문서화 작업도 완비되지 못한 불안정 상태에 머문다","데이터베이스의 저장 공간이 급격히 증가한다","간과해 버렸을 추가 업무 규칙 또는 업무 논리를 놓칠 수 있다","데이터 종속성에 대한 결정을 어렵게 하여 모델의 논리적 완성과 부분집합 식별 능력을 제한한다"],"a":1,"e":"저장 공간 급증은 M:M 미해소의 문제점으로 제시되지 않았다.","s":"2장 7절 M:M 관계 해소의 의의"},
  {"id":"C4-219","ch":4,"no":219,"q":"이력 관리 대상 선정을 위한 사용자 조사 항목으로 제시되지 않은 것은?","c":["변경 내역을 감시할 필요가 있는가","시간의 경과에 따라 데이터·관계가 변할 수 있는가","과거의 데이터를 조회하거나 과거 버전을 보관할 필요가 있는가","데이터 건수가 100만 건을 초과하는가"],"a":3,"e":"데이터 건수는 이력 관리 대상 선정 조사 항목이 아니다.","s":"2장 8절 이력 관리 대상 선정"},
  {"id":"C4-220","ch":4,"no":220,"q":"이력 데이터의 종류에 대한 설명으로 옳지 않은 것은?","c":["진행 이력 - 업무의 진행에 따라 데이터를 이력 정보로 남겨야 하는 경우(예: 주문 업무 처리)","시점 이력 - 데이터 변경의 시작 시점부터 종료 시점까지 관리하는 형태","발생 이력 - 어떤 데이터가 발생할 때마다 이력 정보를 남기는 경우(예: 고객의 웹사이트 접속 데이터)","변경 이력 - 데이터가 변경될 때마다 변경된 새로운 정보를 이력 정보로 남기는 경우"],"a":1,"e":"시점 이력은 이력 '관리 형태'이며, 시작~종료 시점까지 관리하는 것은 선분 이력이다.","s":"2장 8절 이력 데이터의 종류"},
  {"id":"C4-221","ch":4,"no":221,"q":"발생 이력(이벤트성) 데이터를 관리하는 방법에 대한 설명으로 옳은 것은?","c":["반드시 이벤트 발생 시에만 생성해야 한다","발생 이력은 선분 이력으로만 관리할 수 있다","이벤트가 발생할 때에만 이력 데이터를 생성하는 방법과 이력이 발생하지 않더라도 날마다 데이터를 생성하는 방법이 있으며, 후자는 완벽한 이력관리가 불가능하다","반드시 날마다 데이터를 생성해야 한다"],"a":2,"e":"이벤트 발생 시 생성 또는 날마다 생성하는 방법이 있으며, 날마다 생성 방법은 완벽한 이력관리가 불가능하다.","s":"2장 8절 이력 데이터의 종류"},
  {"id":"C4-222","ch":4,"no":222,"q":"시점 이력의 단점으로 가장 적절한 것은?","c":["데이터 무결성을 보장할 수 없다","특정한 시점의 데이터를 추출하고자 할 경우 MAX(발생시각) 등 불필요한 작업을 수행해야 한다","저장 공간이 선분 이력보다 훨씬 많이 필요하다","인덱스를 생성할 수 없다"],"a":1,"e":"시점 이력은 특정 시점 데이터 추출 시 <= 조건의 MAX 값을 구해야 하는 불필요한 작업이 발생한다.","s":"2장 8절 이력 관리 형태"},
  {"id":"C4-223","ch":4,"no":223,"q":"선분 이력의 의미에 대한 설명으로 옳지 않은 것은?","c":["특정 시점 값을 '=' 연산자로 찾을 수 있다","부등식(시작점 <= 값 <= 종료점) 또는 Between 연산자로 조회한다","어떤 점이나 반드시 하나의 선분을 통과한다","선분이 아무리 길어도 레코드는 하나이다"],"a":0,"e":"선분 이력에서 특정 값을 '=' 로 찾을 수는 없으며, 그 값이 통과하는 선분을 부등식이나 Between으로 찾는다.","s":"2장 8절 선분 이력"},
  {"id":"C4-224","ch":4,"no":224,"q":"인스턴스 레벨 이력 관리의 특징으로 옳지 않은 것은?","c":["다른 이력 관리 유형에 비해 저장 공간을 절약할 수 있다","한 번의 액세스로 해당 시점의 모든 데이터(스냅샷)를 참조할 수 있다","로그성 데이터를 저장할 목적인 경우 적당한 방법이다","하나 이상의 칼럼에 변경이 발생했을 때 이벤트가 모호해진다"],"a":0,"e":"인스턴스 레벨 이력 관리는 다른 유형에 비해 저장 공간의 낭비를 초래할 수 있다.","s":"2장 8절 선분 이력 관리 유형"},
  {"id":"C4-225","ch":4,"no":225,"q":"속성 레벨 이력 관리의 특징으로 옳지 않은 것은?","c":["변화가 너무 많은 경우에 적용하면 가장 효율적이다","변경 이벤트가 매우 분명하게 관리되어 어떤 데이터가 변경되었는지가 분명하다","하나의 이력 관리 엔터티에서 다른 엔터티와 통합 이력 관리가 가능하다","변화가 발생할 가능성이 매우 낮으면서 이력 관리 대상 속성이 매우 많은 경우에 유리하다"],"a":0,"e":"속성 레벨 이력 관리는 변화가 너무 많은 경우에는 적용이 곤란하다.","s":"2장 8절 선분 이력 관리 유형"},
  {"id":"C4-226","ch":4,"no":226,"q":"주제 레벨 이력 관리의 특징으로 가장 적절한 것은?","c":["변경 이벤트를 전혀 구분할 수 없다","다른 엔터티와의 통합 이력 관리가 불가능하다","인스턴스 레벨과 속성 레벨의 장점을 모두 수용하며 부문에 따라 변경 정도의 차이가 심한 경우 유리하다","저장 공간을 가장 많이 사용하는 방식이다"],"a":2,"e":"주제 레벨은 인스턴스 레벨과 속성 레벨의 장점을 수용하고 부문별 변경 정도 차이가 심한 경우 유리하나, 전체 참조 시 Merge가 발생하는 문제가 있다.","s":"2장 8절 선분 이력 관리 유형"},
  {"id":"C4-227","ch":4,"no":227,"q":"선분 이력에서 식별자 결정에 대한 설명으로 가장 적절한 것은?","c":["부서코드 + 시작일자만으로 충분하다","부서코드 + 종료일자만으로 충분하다","선분 이력은 식별자를 정의하지 않는다","부서코드 + 이력시작일 + 이력종료일을 주키로 하는 것이 유리하나, 물리적으로 유일해도 의미적으로 유일하지 않을 수 있어 별도의 검증 조치를 병행해야 한다"],"a":3,"e":"선분 이력의 의미적 UID는 부서코드+시작일+종료일이 유리하지만 의미적 유일성 검증 조치를 병행해야 하며, 시작일자나 종료일자 단독 사용은 성능 문제를 유발한다.","s":"2장 8절 선분 이력 관리용 식별자 확정"},
  {"id":"C4-228","ch":4,"no":228,"q":"선분 이력에서 종료점 처리에 대한 설명으로 가장 적절한 것은?","c":["종료점을 반드시 NULL로 처리해야 한다","종료점은 관리하지 않아도 된다","종료점은 시작점과 동일하게 설정한다","종료점을 NULL로 두면 논리적으로 타당하나 비교가 불가능하고 인덱스를 사용하지 못해 수행 속도가 저하되므로 최대치(예: 9999/12/31)를 부여한다"],"a":3,"e":"종료점은 최대치를 부여하고 가능한 테이블 생성 시 기본값 제약을 부여하는 것이 수행 속도에 유리하다.","s":"2장 8절 선분 이력에서 종료점 처리 시 주의 사항"},
  {"id":"C4-229","ch":4,"no":229,"q":"이력 관리 시 엔터티 및 관계의 변환에 대한 설명으로 옳지 않은 것은?","c":["1:M 관계를 이력관리하면 M:M 관계로 새로운 엔터티가 도출된다(예: 발령이력)","M:M 관계를 이력관리하면 1:M 관계로 변환된다","속성을 이력관리하면 1:M 관계의 엔터티가 도출된다(예: 전화번호이력)","1:1 관계를 이력관리하면 1:M 관계로 변환된다"],"a":1,"e":"M:M 관계의 이력관리는 식별자에 시작일자·종료일자를 추가하는 방식으로 처리한다.","s":"2장 8절 이력 관리 시 엔터티 및 관계의 변환"},
  {"id":"C4-230","ch":4,"no":230,"q":"논리 데이터 모델 품질 기준 중 '활용성'에 대한 설명으로 가장 적절한 것은?","c":["작성된 모델과 설명 내용이 이해관계자에게 의미를 충분히 전달할 수 있고 업무 변화 시 설계 변경이 최소화되도록 유연하게 설계되어 있음을 의미한다","여러 영역에서 공통 사용되는 데이터 요소가 전사 수준에서 한 번만 정의됨을 의미한다","제반 준수 요건들이 누락 없이 정확하게 준수되었음을 의미한다","데이터 모델이 현행 시스템의 최신 상태를 반영하고 있음을 의미한다"],"a":0,"e":"2번은 일관성, 3번은 준거성, 4번은 최신성에 대한 설명이다.","s":"2장 9절 논리 데이터 모델 품질 검토"},
  {"id":"C4-231","ch":4,"no":231,"q":"논리 데이터 모델 품질 검토의 목적에 대한 설명으로 가장 적절한 것은?","c":["성능과 오류 예방의 관점에서 검토한다","저장 공간 최적화 관점에서 검토한다","보안 강화 관점에서 검토한다","'완벽한 모델'보다 '(조직에) 적합한 모델'의 관점에서 생각해야 한다"],"a":3,"e":"논리 데이터 모델 품질 검토는 '적합한 모델' 관점, 물리 데이터 모델 품질 검토는 '성능'과 '오류 예방' 관점이다.","s":"2장 9절 논리 데이터 모델 품질 검토 개요"},
  {"id":"C4-232","ch":4,"no":232,"q":"논리 데이터 모델 품질 검토 체크리스트 중 '통합 수준' 검토 항목으로 제시되지 않은 것은?","c":["코드 엔터티, 계층구조 엔터티, 배타관계 엔터티의 통합이 고려되었는가","다른 영역에서 동일 목적의 엔터티는 동일 명칭과 구조로 일관되게 사용되었는가","인덱스 구성 칼럼들이 적절하게 선정되었는가","업무 행위의 주체가 될 수 있는 전사관계자와 같은 중요 기준데이터의 통합이 고려되었는가"],"a":2,"e":"인덱스 구성은 물리 데이터 모델 품질 검토 항목이다.","s":"2장 9절 논리 데이터 모델 품질 검토 체크리스트"},
  {"id":"C4-233","ch":4,"no":233,"q":"물리 데이터 모델링에 대한 설명으로 가장 적절하지 않은 것은?","c":["데이터베이스 디자인은 물리 모델을 DBMS 관점의 객체로 생성하는 최적의 설계를 하는 것이다","하나의 논리적 집합(엔터티 또는 서브타입)은 반드시 하나의 테이블이 되어야 한다","논리 데이터 모델을 각 DBMS의 특성을 고려하여 데이터베이스 저장 구조로 변환하는 것이다","물리적 데이터 모델링은 관계 데이터 모델링(RDM)이라고도 한다"],"a":1,"e":"하나의 논리적 집합은 하나 이상의 테이블이 될 수 있으며, 테이블은 경우에 따라 속성의 일부만으로 생성될 수 있다.","s":"3장 1절 물리 데이터 모델 정의"},
  {"id":"C4-234","ch":4,"no":234,"q":"하나의 논리적 데이터 모델로부터 여러 개의 물리적 데이터 모델을 설계하는 경우로 제시되지 않은 것은?","c":["분산 데이터베이스 구축 시 노드별로 원하는 형태의 물리 모델을 생성하고자 할 때","여러 개의 물리 모델을 생성하여 종합적인 비교 검토를 하고자 할 때","물리적 환경 변경에 따라 새로운 목표 물리 모델로 개선하고자 할 때","논리 데이터 모델의 정규화 수준을 높이고자 할 때"],"a":3,"e":"정규화는 논리 모델링 단계의 활동이며, 물리 모델 다중 생성 사유는 분산 DB 구축, 모델 비교, 물리 환경 변화, 형상 관리이다.","s":"3장 1절 논리-물리 데이터 모델"},
  {"id":"C4-235","ch":4,"no":235,"q":"논리 데이터 모델과 물리 데이터 모델의 변환 용어 대응으로 옳지 않은 것은?","c":["Entity → Table","Primary UID → Primary Key","Secondary UID → Foreign Key","Business Constraints → Check Constraints"],"a":2,"e":"Secondary UID는 Unique Key로, Relationship이 Foreign Key로 변환된다.","s":"3장 3절 논리-물리 모델 변환 용어"},
  {"id":"C4-236","ch":4,"no":236,"q":"슈퍼타입 기준 테이블 변환이 유리한 경우로 제시되지 않은 것은?","c":["각 서브타입 속성들의 선택 사양이 명확한 경우","데이터 액세스가 좀 더 간편하고 뷰를 활용하여 각 서브타입만 액세스하거나 수정 가능","서브타입 구분 없는 임의 집합의 가공이 용이하고 다수의 서브타입 통합 시 조인 감소 효과가 큼","복잡한 처리를 하나의 SQL로 통합하기 용이"],"a":0,"e":"각 서브타입 속성들의 선택 사양이 명확한 경우는 서브타입 기준 테이블 변환이 유리하다.","s":"3장 3절 서브타입 변환"},
  {"id":"C4-237","ch":4,"no":237,"q":"슈퍼타입 기준 테이블 변환의 단점으로 제시되지 않은 것은?","c":["테이블의 칼럼 수·블록 수 증가 및 인덱스 크기 증가","처리 시마다 서브타입의 구분(TYPE)이 필요해지는 경우가 많음","서브타입 구분 없이 데이터 처리하는 경우 UNION이 발생함","특정 서브타입의 NOT NULL 제한 불가"],"a":2,"e":"UNION 발생은 서브타입 기준(각각의 테이블로) 변환의 단점이다.","s":"3장 3절 서브타입 변환"},
  {"id":"C4-238","ch":4,"no":238,"q":"서브타입 기준(각각의 테이블로) 변환의 단점으로 제시되지 않은 것은?","c":["서브타입 구분 없이 데이터를 처리하는 경우 UNION이 발생한다","트랜잭션 처리 시 여러 테이블을 처리하는 경우가 증가한다","부분 범위 처리가 불가능해질 수 있고 여러 테이블을 합친 뷰는 조회만 가능하다","전체 테이블 스캔 시 불리하다"],"a":3,"e":"서브타입 기준 변환은 전체 테이블 스캔 시 유리하며 단위 테이블 크기가 감소한다.","s":"3장 3절 서브타입 변환"},
  {"id":"C4-239","ch":4,"no":239,"q":"개별타입 기준 테이블 변환(슈퍼타입과 서브타입을 각각 테이블로)을 적용하기에 적절한 경우로 제시되지 않은 것은?","c":["서브타입에 적은 양의 속성이나 관계를 가진 경우","전체 데이터 처리가 빈번하게 발생하고 서브타입의 처리는 주로 독립적으로 발생하는 경우","테이블을 통합했을 때 칼럼 수가 너무 많아지는 경우 또는 서브타입의 칼럼 수가 많은 경우","트랜잭션이 주로 공통 부분(슈퍼타입)에서 발생하는 경우"],"a":0,"e":"서브타입에 적은 양의 속성이나 관계를 가진 경우는 슈퍼타입 기준 통합 변환이 적합하다.","s":"3장 3절 서브타입 변환"},
  {"id":"C4-240","ch":4,"no":240,"q":"슈퍼타입 기준 테이블 변환 절차의 두 번째 단계로 가장 적절한 것은?","c":["서브타입의 관계를 FK로","슈퍼타입으로 테이블 명칭 부여","서브타입을 구분할 수 있도록 칼럼 추가","슈퍼타입의 속성을 칼럼명으로"],"a":2,"e":"슈퍼타입으로 테이블 명칭 부여 → 서브타입 구분 칼럼 추가 → 슈퍼타입 속성 → 서브타입 속성 → 슈퍼타입 관계 FK → 서브타입 관계 FK 순이다.","s":"3장 3절 슈퍼타입 기준 테이블 변환"},
  {"id":"C4-241","ch":4,"no":241,"q":"일반 속성-칼럼 변환에 대한 설명으로 가장 적절하지 않은 것은?","c":["칼럼 명칭은 속성 명칭과 반드시 일치할 필요는 없으나 혼동을 피하기 위해 표준화된 약어를 사용한다","표준화된 약어의 사용은 SQL 해독 시간을 감소시킨다","SQL의 예약어 사용을 피하며 칼럼 명칭은 짧은 것이 좋다","필수 입력 속성은 Nulls/Unique 란에 U로 표시한다"],"a":3,"e":"필수 입력 속성은 Nulls/Unique 란에 NN(Not Null)으로 표시한다.","s":"3장 3절 속성-칼럼 변환"},
  {"id":"C4-242","ch":4,"no":242,"q":"Primary UID → 기본키 변환 절차에 대한 설명으로 옳지 않은 것은?","c":["PK로 표시된 모든 칼럼은 Nulls/Unique 란에 반드시 NN, U로 표시한다","여러 개의 칼럼으로 UID가 구성된 경우 각각의 칼럼에 NN, U1을 표시한다","또 다른 Unique Key(Secondary UID)가 있다면 U1로 표시한다","엔터티의 Primary UID에 속하는 모든 속성에 PK를 표시한다"],"a":2,"e":"또 다른 Unique Key(Secondary UID)가 있다면 U2로 표시한다.","s":"3장 3절 Primary UID 변환"},
  {"id":"C4-243","ch":4,"no":243,"q":"1:M 관계에서 1쪽이 Mandatory 관계일 때의 변환 시 주의사항으로 옳은 것은?","c":["외래키에 NULL을 허용해야 한다","자식 쪽의 레코드가 반드시 하나 이상 있어야만 부모 쪽의 레코드를 생성할 수 있으며, 자식 레코드 전체 삭제는 불가하고 하나 이상 남기거나 부모·자식을 동시 삭제해야 한다","부모 쪽 레코드를 먼저 생성한 후 자식 레코드를 생성해야 한다","자식 레코드는 언제든지 전체 삭제할 수 있다"],"a":1,"e":"1쪽이 Mandatory이면 자식 레코드가 반드시 하나 이상 있어야 부모 레코드를 생성할 수 있고, 전체 삭제 시 부모·자식 동시 삭제가 필요하다.","s":"3장 3절 1:M 관계 변환"},
  {"id":"C4-244","ch":4,"no":244,"q":"1:1 관계 변환 시 주의 사항으로 옳지 않은 것은?","c":["1:1 관계에 의해 생긴 모든 외래키 부분은 Unique Key가 필수적이다","한쪽이 Optional이고 다른 한쪽이 Mandatory라면 Mandatory 쪽 테이블에 외래키가 생성된다","양쪽 다 Mandatory라면 어느 테이블에 외래키를 생성할 것인지 선택해야 한다","양쪽 다 Optional인 경우 사용 빈도가 낮은 테이블이 외래키를 가지는 것이 유리하다"],"a":3,"e":"양쪽 다 Optional인 경우 보다 빈번하게 사용되는 테이블이 외래키를 가지는 것이 유리하다.","s":"3장 3절 1:1 관계 변환"},
  {"id":"C4-245","ch":4,"no":245,"q":"1:M 순환 관계 변환에 대한 설명으로 옳지 않은 것은?","c":["외래키 칼럼 명칭은 가능한 한 관계 명칭을 반영한다","최상위 관계 속성은 항상 Optional인 형태의 관계이다","외래키는 결코 Null이 될 수 없다(Not Null)","해당 테이블 내에 외래키 칼럼을 추가하며 외래키는 같은 테이블 내 다른 로우의 기본키 칼럼을 참조한다"],"a":2,"e":"최상위 관계 속성이 Optional이므로 순환 관계의 외래키는 Null이 될 수 있다.","s":"3장 3절 1:M 순환 관계 변환"},
  {"id":"C4-246","ch":4,"no":246,"q":"배타적 관계 변환의 '외래키 분리 방법'에 대한 설명으로 옳은 것은?","c":["각각의 관계를 관계 칼럼으로 생성하며 실제 외래키 제약조건을 생성할 수 있고 각 키 칼럼은 Optional이며 추가적인 체크 제약 조건을 생성한다","각각의 관계를 하나의 관계 칼럼으로 생성하며 구분 칼럼을 추가한다","외래키 제약조건을 생성할 수 없다","구분 칼럼이 반드시 필요하다"],"a":0,"e":"외래키 분리 방법은 FK 제약조건 생성이 가능하며 각 키 칼럼이 Optional이고 체크 제약조건을 추가한다. 2·3·4번은 외래키 결합 방법의 특징이다.","s":"3장 3절 배타적 관계 변환"},
  {"id":"C4-247","ch":4,"no":247,"q":"'관리상 필요한 칼럼 추가'에 대한 설명으로 가장 적절한 것은?","c":["논리 모델의 속성을 물리 모델에서 삭제하는 것","반정규화를 통해 중복 칼럼을 생성하는 것","서브타입 구분 칼럼을 추가하는 것","논리 데이터 모델에는 존재하지 않지만 관리상의 이유나 프로그램의 수행 속도를 위해 테이블·칼럼을 추가하는 것(예: 생성일시, 생성 프로세스 ID)"],"a":3,"e":"관리상 필요한 칼럼은 논리 모델에 없지만 관리·성능상 이유로 추가하는 것으로 데이터 등록 일자, 시스템 번호, 생성일시, 생성 프로세스 ID 등이 있다.","s":"3장 3절 관리상 필요한 칼럼 추가"},
  {"id":"C4-248","ch":4,"no":248,"q":"데이터 타입 선택 시 '정말 숫자 데이터인지 판단한다'는 기준의 예로 가장 적절한 것은?","c":["코드값은 항상 숫자 타입으로 정의해야 한다","주민등록번호는 숫자처럼 보이지만 수치 연산을 하지 않으므로 숫자 타입이 아니다","금액은 수치 연산을 하므로 문자 타입이 적절하다","날짜는 숫자 타입으로 정의해야 한다"],"a":1,"e":"주민등록번호는 숫자처럼 보이지만 수치 연산을 하지 않으므로 숫자 타입으로 정의하지 않는다.","s":"3장 3절 데이터 타입 선택"},
  {"id":"C4-249","ch":4,"no":249,"q":"데이터 표준 적용 대상으로 제시되지 않은 것은?","c":["인덱스, 뷰","SQL 실행 계획","데이터베이스, 스토리지 그룹, 테이블스페이스","테이블, 칼럼"],"a":1,"e":"데이터 표준 적용 대상은 데이터베이스, 스토리지 그룹, 테이블스페이스, 테이블, 칼럼, 인덱스, 뷰이다.","s":"3장 3절 데이터 표준 적용 대상"},
  {"id":"C4-250","ch":4,"no":250,"q":"테이블 명명 순서로 제시된 것으로 옳은 것은?","c":["업무 영역 + 주제어 수식어 + 주제어 + 분류어 수식어 + 분류어 + 접미사","주제어 + 업무 영역 + 분류어 + 접미사","분류어 + 주제어 + 업무 영역","접미사 + 주제어 + 분류어 + 업무 영역"],"a":0,"e":"테이블 명명 순서는 업무 영역 + 주제어 수식어 + 주제어 + 분류어 수식어 + 분류어 + 접미사 순이다.","s":"3장 3절 데이터 표준 적용 방법"}
  ]
